import { test, expect } from '@playwright/test';

test.describe('User Login with Valid Credentials', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log in with valid credentials and redirect to dashboard', async ({ page }) => {
    // Listen for the login API call
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email');
    await expect(emailInput).toBeVisible();
    await emailInput.fill('user@example.com');

    // Locate and fill password input using getByLabel
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();
    await passwordInput.fill('ValidPassword123!');

    // Click login button using getByRole
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();
    await loginButton.click();

    // Wait for navigation and verify dashboard content
    await page.waitForURL('/dashboard');
    await expect(page).toHaveURL(/.*dashboard/);

    // Verify welcome message using getByRole for heading
    const welcomeHeading = page.getByRole('heading', { name: /welcome back/i });
    await expect(welcomeHeading).toBeVisible();
    await expect(welcomeHeading).toContainText('Welcome back');

    // Verify user profile icon and logout button
    const profileIcon = page.getByRole('img', { name: /user profile/i });
    await expect(profileIcon).toBeVisible();

    const logoutButton = page.getByRole('button', { name: /log out/i });
    await expect(logoutButton).toBeVisible();
  });

  test('should display error message when login fails with invalid credentials', async ({ page }) => {
    // Mock failed login response
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');

    // Locate and fill password input using getByLabel
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('WrongPassword123!');

    // Click login button using getByRole
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/invalid email or password/i);
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Invalid email or password');

    // Verify still on login page
    await expect(page).toHaveURL(/.*login/);

    // Verify form fields retain values
    await expect(emailInput).toHaveValue('user@example.com');
    await expect(passwordInput).toHaveValue('WrongPassword123!');

    // Verify dashboard content is not visible
    const welcomeMessage = page.getByRole('heading', { name: /welcome back/i });
    await expect(welcomeMessage).not.toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

test.describe('Authentication - Incorrect Password Error Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display error message when user enters incorrect password', async ({ page }) => {
    // Get email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');

    // Get password input using getByLabel
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword123');

    // Setup API interception before clicking
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Click login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Assert error message is visible and contains correct text
    const errorMessage = page.getByText('Invalid password');
    await expect(errorMessage).toBeVisible();

    // Assert error message has appropriate styling
    const errorContainer = page.locator('[data-testid="error-message"]');
    await expect(errorContainer).toContainText('Invalid password');

    // Assert password field is still visible and accessible
    await expect(passwordInput).toBeVisible();

    // Assert login button is still enabled for retry
    await expect(loginButton).not.toBeDisabled();
  });

  test('should display error message when password field is empty', async ({ page }) => {
    // Get email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');

    // Get password input using getByLabel (must use getByLabel/getByRole twice)
    const passwordInput = page.getByLabel('Password');

    // Setup API interception
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Click login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Assert validation error message is displayed
    const validationError = page.getByText('Password is required');
    await expect(validationError).toBeVisible();

    // Assert error styling is applied to password field
    await expect(passwordInput).toHaveAttribute('aria-invalid', 'true');

    // Verify user can correct the error and form recovers
    await passwordInput.fill('correctpassword123');
    await expect(passwordInput).not.toHaveAttribute('aria-invalid', 'true');

    // Assert submit button is now enabled
    await expect(loginButton).not.toBeDisabled();
  });
});

import { test, expect } from '@playwright/test';

test.describe('User Logout - Secure Session Termination', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.getByLabel('Email Address').fill('testuser@example.com');
    await page.getByLabel('Password').fill('ValidPassword123');
    await page.getByRole('button', { name: 'Sign In' }).click();
    await page.waitForURL('**/dashboard');
    await expect(page.getByRole('heading', { name: 'Dashboard' })).toBeVisible();
  });

  test('should successfully log out user and clear session', async ({ page }) => {
    const logoutPromise = page.waitForResponse(response => 
      response.url().includes('/api/auth/logout') && response.status() === 200
    );

    await page.getByRole('button', { name: /user menu/i }).click();
    await page.getByRole('menuitem', { name: /log out/i }).click();

    await logoutPromise;

    await expect(page).toHaveURL('**/login');
    await expect(page.getByRole('heading', { name: /sign in/i })).toBeVisible();

    const authToken = await page.evaluate(() => sessionStorage.getItem('authToken'));
    expect(authToken).toBeNull();
  });

  test('should handle logout failure and display error message', async ({ page }) => {
    await page.route('**/api/auth/logout', route => {
      route.abort('failed');
    });

    await page.getByRole('button', { name: /user menu/i }).click();
    await page.getByRole('menuitem', { name: /log out/i }).click();

    await page.waitForTimeout(1000);

    await expect(page.getByText(/unable to log out|logout failed/i)).toBeVisible();
    await expect(page.getByRole('heading', { name: 'Dashboard' })).toBeVisible();
    await expect(page).toHaveURL('**/dashboard');
  });
});

import { test, expect } from '@playwright/test';

test.describe('Authentication - Protected Page Redirect', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should redirect unauthenticated user to login when accessing protected page', async ({ page }) => {
    // Clear all cookies and storage to ensure unauthenticated state
    await page.context().clearCookies();
    await page.evaluate(() => localStorage.clear());
    await page.evaluate(() => sessionStorage.clear());

    // Attempt to visit protected dashboard page
    await page.goto('/dashboard', { waitUntil: 'networkidle' });

    // Verify redirect to login page occurred
    await expect(page).toHaveURL(/\/login/);

    // Verify login form is visible
    const loginForm = page.getByRole('form');
    await expect(loginForm).toBeVisible();

    // Verify login button exists and is enabled
    const loginButton = page.getByRole('button', { name: /login|sign in/i });
    await expect(loginButton).toBeVisible();
    await expect(loginButton).toBeEnabled();

    // Verify email input field is present and can be located by label
    const emailInput = page.getByLabel(/email|username/i);
    await expect(emailInput).toBeVisible();

    // Verify password input field is present and can be located by label
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();

    // Verify form title or heading contains login text
    const formTitle = page.getByRole('heading', { name: /login|sign in/i });
    await expect(formTitle).toBeVisible();
  });

  test('should handle rapid redirect attempts and prevent infinite loops', async ({ page }) => {
    // Clear authentication state
    await page.context().clearCookies();
    await page.evaluate(() => localStorage.clear());
    await page.evaluate(() => sessionStorage.clear());

    // Setup API intercept for auth verification
    await page.route('**/api/auth/verify', (route) => {
      route.abort('blockedbyclient');
    });

    // Attempt to access protected resource
    await page.goto('/dashboard', { waitUntil: 'domcontentloaded' });

    // Verify we're on login page after first attempt
    await expect(page).toHaveURL(/\/login/);

    // Verify login form is present using role-based selector
    const emailInput = page.getByLabel(/email|username/i);
    await expect(emailInput).toBeVisible();

    // Try accessing another protected page
    await page.goto('/profile', { waitUntil: 'domcontentloaded' });

    // Should still be on login, not in redirect loop
    await expect(page).toHaveURL(/\/login/);

    // Verify no error message indicating redirect loop
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toHaveCount(0);

    // Verify login button is still available and enabled
    const loginButton = page.getByRole('button', { name: /login|sign in/i });
    await expect(loginButton).toBeVisible();
    await expect(loginButton).toBeEnabled();

    // Verify form is still functional by filling it
    const passwordInput = page.getByLabel(/password/i);
    await emailInput.fill('test@example.com');
    await passwordInput.fill('password123');

    // Verify form submission button is available
    await expect(loginButton).toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

test.describe('Password Reset Confirmation Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/forgot-password');
  });

  test('should display confirmation message after successful password reset', async ({ page }) => {
    // Intercept the password reset API call
    await page.route('**/api/auth/reset-password', (route) => {
      route.abort('failed');
    });

    // Setup successful API response
    await page.route('**/api/auth/reset-password', (route) => {
      route.continue();
      route.response().then((response) => {
        if (response.status() === 200) {
          return;
        }
      });
    });

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email address');
    await emailInput.fill('user@example.com');

    // Locate and click reset button using getByRole
    const resetButton = page.getByRole('button', { name: /reset password/i });
    await resetButton.click();

    // Wait for the confirmation message to appear
    const confirmationMessage = page.getByText('Password reset successful');
    await expect(confirmationMessage).toBeVisible();

    // Verify the message has correct styling
    const messageContainer = page.locator('[data-testid="confirmation-message"]');
    await expect(messageContainer).toHaveClass(/success-alert/);

    // Verify redirect link is visible using getByRole
    const loginLink = page.getByRole('link', { name: /return to login/i });
    await expect(loginLink).toBeVisible();
  });

  test('should not display confirmation message when reset fails', async ({ page }) => {
    // Mock failed API response
    await page.route('**/api/auth/reset-password', (route) => {
      route.abort('failed');
    });

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email address');
    await emailInput.fill('invalid-email');

    // Locate and click reset button using getByRole
    const resetButton = page.getByRole('button', { name: /reset password/i });
    await resetButton.click();

    // Wait briefly for potential error response
    await page.waitForTimeout(1000);

    // Verify success confirmation message does NOT appear
    const successMessage = page.getByText('Password reset successful');
    await expect(successMessage).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid email/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is still on the reset page
    await expect(page).toHaveURL(/forgot-password/);
  });
});

import { test, expect } from '@playwright/test';

test.describe('Login Form Empty Field Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should prevent form submission when email and password fields are empty', async ({ page }) => {
    // Locate and click the submit button using getByRole
    const submitButton = page.getByRole('button', { name: 'Sign In' });
    await submitButton.click();

    // Verify error messages appear for both fields using getByRole and getByText
    const emailError = page.getByText('Email is required');
    await expect(emailError).toBeVisible();

    const passwordError = page.getByText('Password is required');
    await expect(passwordError).toBeVisible();

    // Verify the form was not submitted (URL should still contain /login)
    await expect(page).toHaveURL(/\/login/);
    const loginForm = page.locator('[data-testid="login-form"]');
    await expect(loginForm).toBeVisible();
  });

  test('should prevent form submission when only email field is filled and password is empty', async ({ page }) => {
    // Fill the email field using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');

    // Verify email field has the correct value
    await expect(emailInput).toHaveValue('user@example.com');

    // Click submit button using getByRole
    const submitButton = page.getByRole('button', { name: 'Sign In' });
    await submitButton.click();

    // Verify error message appears only for password field
    const passwordError = page.getByText('Password is required');
    await expect(passwordError).toBeVisible();

    // Verify no error message for email field
    const emailError = page.getByText('Email is required');
    await expect(emailError).not.toBeVisible();

    // Verify the form was not submitted
    await expect(page).toHaveURL(/\/login/);
  });
});

import { test, expect } from '@playwright/test';

test.describe('Remember Me Checkbox - Authentication', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.context().clearCookies();
    await page.evaluate(() => localStorage.clear());
  });

  test('should persist user session when Remember Me is checked', async ({ page }) => {
    // Fill login form
    const emailField = page.getByLabel('Email Address');
    const passwordField = page.getByLabel('Password');
    const rememberMeCheckbox = page.getByRole('checkbox', { name: /remember me/i });
    const loginButton = page.getByRole('button', { name: /sign in|login/i });

    await emailField.fill('testuser@example.com');
    await passwordField.fill('securePassword123');

    // Check Remember Me checkbox
    await rememberMeCheckbox.click();
    await expect(rememberMeCheckbox).toBeChecked();

    // Intercept login API call
    const loginPromise = page.waitForResponse(response => 
      response.url().includes('/api/auth/login') && response.status() === 200
    );

    // Submit login form
    await loginButton.click();
    const response = await loginPromise;
    const responseBody = await response.json();
    expect(responseBody.rememberMeEnabled).toBe(true);

    // Verify redirect to dashboard
    await expect(page).toHaveURL(/\/dashboard/);

    // Verify session token is stored
    const sessionToken = await page.evaluate(() => localStorage.getItem('sessionToken'));
    expect(sessionToken).toBeTruthy();
    const rememberMeToken = await page.evaluate(() => localStorage.getItem('rememberMeToken'));
    expect(rememberMeToken).toBeTruthy();

    // Verify welcome message appears
    const welcomeMessage = page.getByText(/welcome/i);
    await expect(welcomeMessage).toBeVisible();

    // Verify user profile is accessible
    const profileMenu = page.getByRole('button', { name: /profile|account/i });
    await expect(profileMenu).toBeVisible();
  });

  test('should not persist session when Remember Me is unchecked', async ({ page }) => {
    // Fill login form without checking Remember Me
    const emailField = page.getByLabel('Email Address');
    const passwordField = page.getByLabel('Password');
    const rememberMeCheckbox = page.getByRole('checkbox', { name: /remember me/i });
    const loginButton = page.getByRole('button', { name: /sign in|login/i });

    await emailField.fill('testuser@example.com');
    await passwordField.fill('securePassword123');

    // Verify Remember Me is unchecked by default
    await expect(rememberMeCheckbox).not.toBeChecked();

    // Intercept and verify login request
    const loginPromise = page.waitForResponse(response =>
      response.url().includes('/api/auth/login') && response.status() === 200
    );

    // Submit login form
    await loginButton.click();
    const response = await loginPromise;
    const responseBody = await response.json();
    expect(responseBody.rememberMeEnabled).toBe(false);

    // Verify successful login
    await expect(page).toHaveURL(/\/dashboard/);
    const welcomeText = page.getByText(/welcome/i);
    await expect(welcomeText).toBeVisible();

    // Simulate session expiration by clearing storage
    await page.evaluate(() => {
      localStorage.clear();
      sessionStorage.clear();
    });

    // Clear cookies to fully simulate session end
    await page.context().clearCookies();

    // Navigate to dashboard
    await page.goto('/dashboard');

    // Should be redirected to login page
    await expect(page).toHaveURL(/\/login/);

    // Verify session expired message
    const sessionExpiredMsg = page.getByText(/session expired|login again/i);
    await expect(sessionExpiredMsg).toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

test.describe('Login Loading Spinner', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display loading spinner while login request is processing', async ({ page }) => {
    await page.route('**/api/auth/login', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.abort();
      await route.continue();
    });

    await page.route('**/api/auth/login', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.fulfill({
        status: 200,
        body: JSON.stringify({ token: 'abc123', userId: 'user1' }),
      });
    });

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('password123');

    const loginButton = page.getByRole('button', { name: 'Login' });
    await loginButton.click();

    const spinner = page.locator('[data-testid="loading-spinner"]');
    await expect(spinner).toBeVisible();

    const spinnerText = page.getByText('Logging in...');
    await expect(spinnerText).toBeVisible();

    await page.waitForNavigation();
    await expect(spinner).not.toBeVisible();
    await expect(page).toHaveURL(/.*dashboard/);
  });

  test('should hide spinner and display error message on failed login request', async ({ page }) => {
    await page.route('**/api/auth/login', async (route) => {
      await route.fulfill({
        status: 401,
        body: JSON.stringify({ error: 'Invalid credentials' }),
      });
    });

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword');

    const loginButton = page.getByRole('button', { name: 'Login' });
    await loginButton.click();

    const spinner = page.locator('[data-testid="loading-spinner"]');
    await expect(spinner).toBeVisible();

    await page.waitForTimeout(1500);

    await expect(spinner).not.toBeVisible();

    const errorMessage = page.getByText('Invalid credentials');
    await expect(errorMessage).toBeVisible();
    await expect(page).toHaveURL(/.*login/);
  });
});

import { test, expect } from '@playwright/test';

test.describe('Account Lockout After 5 Failed Login Attempts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should lock account after 5 consecutive failed login attempts', async ({ page }) => {
    const testEmail = 'testuser@example.com';
    const wrongPassword = 'wrongpassword123';

    // Attempt 1
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill(testEmail);
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill(wrongPassword);
    const loginButton = page.getByRole('button', { name: /sign in|login/i });
    await loginButton.click();
    const errorMsg = page.getByText('Invalid credentials');
    await expect(errorMsg).toBeVisible();

    // Attempt 2
    await passwordInput.fill(wrongPassword);
    await loginButton.click();
    await expect(errorMsg).toBeVisible();

    // Attempt 3
    await passwordInput.fill(wrongPassword);
    await loginButton.click();
    await expect(errorMsg).toBeVisible();

    // Attempt 4
    await passwordInput.fill(wrongPassword);
    await loginButton.click();
    await expect(errorMsg).toBeVisible();

    // Attempt 5 - Should trigger account lockout
    await passwordInput.fill(wrongPassword);
    await page.route('**/api/auth/login', route => {
      route.abort();
    });
    await loginButton.click();

    const lockoutMessage = page.getByText(/account locked/i);
    await expect(lockoutMessage).toBeVisible();
    await expect(loginButton).toBeDisabled();
  });

  test('should prevent login with correct credentials when account is locked', async ({ page }) => {
    const testEmail = 'lockeduser@example.com';
    const correctPassword = 'correctpassword123';

    // Mock locked account response
    await page.route('**/api/auth/login', route => {
      route.abort('failed');
    });

    const emailField = page.getByLabel('Email Address');
    await emailField.fill(testEmail);
    const passwordField = page.getByLabel('Password');
    await passwordField.fill(correctPassword);
    const submitButton = page.getByRole('button', { name: /sign in|login/i });
    await submitButton.click();

    const lockedBanner = page.getByText(/account is locked|temporarily locked/i);
    await expect(lockedBanner).toBeVisible();
    await expect(submitButton).toBeDisabled();

    const supportLink = page.getByText(/contact support|unlock/i);
    await expect(supportLink).toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

test.describe('Google OAuth Login', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log in with valid Google OAuth credentials', async ({ page, context }) => {
    // Mock Google OAuth callback API
    await page.route('**/api/auth/google/callback', route => {
      route.abort();
    });

    await page.route('**/api/auth/google/callback', route => {
      route.continue({
        status: 200,
        body: JSON.stringify({
          success: true,
          token: 'mock_jwt_token_12345',
          user: {
            id: 'user_123',
            email: 'testuser@gmail.com',
            name: 'Test User',
            picture: 'https://example.com/picture.jpg'
          }
        })
      });
    });

    // Mock user profile API
    await page.route('**/api/user/profile', route => {
      route.continue({
        status: 200,
        body: JSON.stringify({
          id: 'user_123',
          email: 'testuser@gmail.com',
          name: 'Test User',
          authenticated: true
        })
      });
    });

    // Locate and click Google Login button by role
    const googleLoginBtn = page.getByRole('button', { name: /sign in with google/i });
    await expect(googleLoginBtn).toBeVisible();
    await googleLoginBtn.click();

    // Listen for popup window
    const [popup] = await Promise.all([
      context.waitForEvent('page'),
      page.getByRole('button', { name: /sign in with google/i }).click()
    ]).catch(() => [null]); // Handle case where popup doesn't open

    // Wait for redirect to dashboard
    await page.waitForURL('**/dashboard', { timeout: 10000 });
    expect(page.url()).toContain('/dashboard');

    // Verify user greeting is displayed
    const userGreeting = page.getByText(/Test User/);
    await expect(userGreeting).toBeVisible();

    // Verify user email is displayed
    const userEmail = page.getByText('testuser@gmail.com');
    await expect(userEmail).toBeVisible();

    // Verify authentication token is stored in localStorage
    const authToken = await page.evaluate(() => localStorage.getItem('auth_token'));
    expect(authToken).toBe('mock_jwt_token_12345');

    // Verify logout button is available
    const logoutBtn = page.getByRole('button', { name: /logout/i });
    await expect(logoutBtn).toBeVisible();
  });

  test('should handle Google OAuth cancellation and network errors gracefully', async ({ page }) => {
    // Mock failed OAuth response for cancellation
    await page.route('**/api/auth/google/callback', route => {
      route.continue({
        status: 401,
        body: JSON.stringify({
          success: false,
          error: 'oauth_cancelled',
          message: 'User cancelled Google OAuth flow'
        })
      });
    });

    // Locate and interact with Google Login button
    const googleLoginBtn = page.getByRole('button', { name: /sign in with google/i });
    await expect(googleLoginBtn).toBeVisible();
    await googleLoginBtn.click();

    // Verify error message is displayed
    const errorMsg = page.getByText(/authentication failed/i);
    await expect(errorMsg).toBeVisible();

    // Verify user remains on login page
    expect(page.url()).toContain('/login');

    // Verify no authentication token is stored
    const authToken = await page.evaluate(() => localStorage.getItem('auth_token'));
    expect(authToken).toBeNull();

    // Test network timeout scenario
    await page.route('**/api/auth/google/callback', route => {
      route.abort('timedout');
    });

