import { test, expect } from '@playwright/test';

test.describe('Session Expiration after 30 Minutes of Inactivity', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.getByLabel('Email').fill('testuser@example.com');
    await page.getByLabel('Password').fill('ValidPassword123!');
    await page.getByRole('button', { name: 'Log In' }).click();
    await page.getByTestId('dashboard-page').waitFor({ state: 'visible' });
  });

  test('should expire session after 30 minutes of inactivity', async ({ page }) => {
    // Verify user is logged in
    await expect(page.getByRole('link', { name: 'Profile' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Log Out' })).toBeVisible();

    // Mock session validation API response after timeout
    await page.route('/api/session/validate', async (route) => {
      await route.abort('timedout');
    });

    // Simulate 30 minutes of inactivity by advancing browser time
    await page.context().addInitScript(() => {
      window.__testTime = Date.now() + 30 * 60 * 1000;
    });

    // Trigger a user action that checks session validity
    await page.getByRole('button', { name: 'Refresh Dashboard' }).click();

    // Verify session expired message and redirect to login
    await expect(page.getByText('Your session has expired')).toBeVisible();
    await expect(page.getByRole('heading', { name: 'Sign In' })).toBeVisible();
    await expect(page.getByRole('link', { name: 'Profile' })).not.toBeVisible();
    await expect(page.getByRole('button', { name: 'Log Out' })).not.toBeVisible();
  });

  test('should keep session alive when user is active within 30-minute window', async ({ page }) => {
    // Verify initial logged-in state
    await expect(page.getByRole('link', { name: 'Profile' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Settings' })).toBeVisible();

    // Mock successful session refresh responses
    let refreshCount = 0;
    await page.route('/api/session/refresh', async (route) => {
      refreshCount++;
      await route.continue();
    });

    // Simulate user activity at regular intervals within 30-minute window
    // Activity 1: 5 minutes
    await page.waitForTimeout(1000);
    await page.getByRole('button', { name: 'Settings' }).click();

    // Activity 2: 10 minutes
    await page.waitForTimeout(1000);
    await page.getByRole('link', { name: 'Dashboard' }).click();

    // Activity 3: 20 minutes
    await page.waitForTimeout(1000);
    await page.getByRole('button', { name: 'Refresh Dashboard' }).click();

    // Verify session is still valid
    await expect(page.getByRole('link', { name: 'Profile' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Log Out' })).toBeVisible();
    await expect(page.getByText('Your session has expired')).not.toBeVisible();
    await expect(page.getByTestId('dashboard-page')).toBeVisible();
  });
});

