    await expect(errorMessage).toBeVisible();
    const captchaContainer = page.locator('[data-testid="captcha-container"]');
    await expect(captchaContainer).not.toBeVisible();

    // Third failed attempt - CAPTCHA should appear
    await passwordInput.fill('wrongpassword3');
    await loginButton.click();
    await expect(errorMessage).toBeVisible();
