    await expect(captchaText).toBeVisible();

    // Verify login button is disabled until CAPTCHA is solved
    await expect(loginButton).toBeDisabled();
  });

  test('should not display CAPTCHA if login succeeds before 3 attempts', async ({ page }) => {
    // First failed attempt
