test.describe('Date Picker - Past Date Prevention for Future Bookings', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/booking');
  });

  test('should allow selecting a future date and successfully submit the booking form', async ({ page }) => {
    // Get today's date and calculate a future date (7 days from now)
    const today = new Date();
    const futureDate = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
    const formattedFutureDate = futureDate.toISOString().split('T')[0];

    // Set up API interception for booking submission
    await page.route('**/api/bookings', route => {
      route.continue();
    });

    // Click on the date picker input using getByRole
    const datePickerButton = page.getByRole('button', { name: /select booking date/i });
    await datePickerButton.click();

    // Wait for calendar to be visible and select the future date
    const calendarDay = page.locator(`[data-testid="calendar-day-${formattedFutureDate}"]`);
    await expect(calendarDay).toBeVisible();
    await calendarDay.click();

    // Verify the selected date is displayed in the input
    const dateInput = page.getByLabel(/booking date/i);
    await expect(dateInput).toHaveValue(formattedFutureDate);

    // Fill in guest name using getByLabel
    const guestNameInput = page.getByLabel(/guest name/i);
    await guestNameInput.fill('John Doe');

    // Fill in guest email
    const guestEmailInput = page.getByLabel(/guest email/i);
    await guestEmailInput.fill('john@example.com');

    // Fill in booking description
    const descriptionInput = page.getByPlaceholder(/booking details/i);
    await descriptionInput.fill('Standard booking');

    // Submit the form using getByRole
    const submitButton = page.getByRole('button', { name: /submit booking/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/booking confirmed/i);
    await expect(successMessage).toBeVisible();
  });

  test('should prevent selecting past dates and display validation error', async ({ page }) => {
    // Get today's date and calculate a past date (3 days ago)
    const today = new Date();
    const pastDate = new Date(today.getTime() - 3 * 24 * 60 * 60 * 1000);
    const formattedPastDate = pastDate.toISOString().split('T')[0];

    // Click on the date picker button using getByRole
    const datePickerButton = page.getByRole('button', { name: /select booking date/i });
    await datePickerButton.click();

    // Wait for calendar to appear and verify past date is disabled
    const calendarDay = page.locator(`[data-testid="calendar-day-${formattedPastDate}"]`);
    await expect(calendarDay).toBeVisible();
    await expect(calendarDay).toBeDisabled();

    // Verify past date has disabled styling
    const disabledClass = await calendarDay.getAttribute('class');
    expect(disabledClass).toContain('disabled-date');

    // Fill in guest information
    const guestNameInput = page.getByLabel(/guest name/i);
    await guestNameInput.fill('Jane Doe');

    const guestEmailInput = page.getByLabel(/guest email/i);
    await guestEmailInput.fill('jane@example.com');

    // Try to submit without selecting a valid future date
    const submitButton = page.getByRole('button', { name: /submit booking/i });
    await submitButton.click();

    // Verify validation error message appears
    const errorMessage = page.getByText(/please select a future date/i);
    await expect(errorMessage).toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText(/booking confirmed/i);
    await expect(successMessage).not.toBeVisible();
  });
});

