test.describe('File Upload - File Size Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully upload a file smaller than 5MB', async ({ page }) => {
    // Locate file input by role/label
    const fileInput = page.getByLabel('Upload file');
    await expect(fileInput).toBeVisible();

    // Create a 2MB test file
    const tempFile = path.join(__dirname, 'temp-valid.pdf');
    const buffer = Buffer.alloc(2 * 1024 * 1024);
    fs.writeFileSync(tempFile, buffer);

    try {
      // Set file input value
      await fileInput.setInputFiles(tempFile);

      // Verify file is selected using getByRole
      const fileNameDisplay = page.getByRole('region', { name: /file name/i });
      await expect(fileNameDisplay).toContainText('temp-valid.pdf');

      // Verify file size display
      const fileSizeDisplay = page.getByRole('status', { name: /file size/i });
      await expect(fileSizeDisplay).toContainText('2 MB');

      // Locate upload button by role
      const uploadButton = page.getByRole('button', { name: /upload/i });
      await expect(uploadButton).toBeEnabled();

      // Intercept API and click upload
      await page.route('POST', '/api/files/upload', async route => {
        await route.continue();
      });

      await uploadButton.click();

      // Verify success message
      const successMessage = page.getByText(/File uploaded successfully/i);
      await expect(successMessage).toBeVisible();
    } finally {
      // Cleanup temp file
      if (fs.existsSync(tempFile)) {
        fs.unlinkSync(tempFile);
      }
    }
  });

  test('should reject files larger than 5MB with error message', async ({ page }) => {
    // Locate file input by label
    const fileInput = page.getByLabel('Upload file');
    await expect(fileInput).toBeVisible();

    // Create an 8MB test file
    const tempFile = path.join(__dirname, 'temp-large.pdf');
    const buffer = Buffer.alloc(8 * 1024 * 1024);
    fs.writeFileSync(tempFile, buffer);

    try {
      // Set file input value
      await fileInput.setInputFiles(tempFile);

      // Verify file is selected
      const fileNameDisplay = page.getByRole('region', { name: /file name/i });
      await expect(fileNameDisplay).toContainText('temp-large.pdf');

      // Verify error message appears
      const errorMessage = page.getByText(/File size exceeds 5MB limit/i);
      await expect(errorMessage).toBeVisible();

      // Verify file size warning display
      const fileSizeDisplay = page.getByRole('status', { name: /file size/i });
      await expect(fileSizeDisplay).toContainText('8 MB');
      const warningClass = await fileSizeDisplay.evaluate(el => 
        el.classList.contains('size-warning')
      );
      expect(warningClass).toBe(true);

      // Locate and verify upload button is disabled
      const uploadButton = page.getByRole('button', { name: /upload/i });
      await expect(uploadButton).toBeDisabled();

      // Verify no upload request is sent
      let uploadCalled = false;
      await page.route('POST', '/api/files/upload', async route => {
        uploadCalled = true;
        await route.continue();
      });

      // Attempt to click disabled button (should not trigger)
      try {
        await uploadButton.click();
      } catch {
        // Expected - button is disabled
      }

      // Wait a moment and verify upload was not called
      await page.waitForTimeout(500);
      expect(uploadCalled).toBe(false);

      // Verify error message persists
      await expect(errorMessage).toBeVisible();
    } finally {
      // Cleanup temp file
      if (fs.existsSync(tempFile)) {
