test.describe('Form Validation - Submit Button Disabled Until All Required Fields Filled', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('Happy path - Submit button becomes enabled when all required fields are filled', async ({ page }) => {
    // Verify submit button is initially disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Fill in first required field using getByLabel
    const firstNameInput = page.getByLabel(/first name/i);
    await firstNameInput.fill('John');
    await expect(submitButton).toBeDisabled();

    // Fill in second required field using getByLabel
    const lastNameInput = page.getByLabel(/last name/i);
    await lastNameInput.fill('Doe');
    await expect(submitButton).toBeDisabled();

    // Fill in email required field using getByPlaceholder
    const emailInput = page.getByPlaceholder(/email/i);
    await emailInput.fill('john.doe@example.com');

    // Verify submit button is now enabled
    await expect(submitButton).not.toBeDisabled();
    await expect(submitButton).toBeVisible();

    // Set up network intercept and submit
    const responsePromise = page.waitForResponse(response => 
      response.url().includes('/api/form-submit') && response.status() === 200
    );
    await submitButton.click();
    const response = await responsePromise;
    expect(response.status()).toBe(200);

    // Verify success message using getByRole
    const successMessage = page.getByRole('status');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('Form submitted successfully');
  });

  test('Negative path - Submit button remains disabled when required fields are partially filled or cleared', async ({ page }) => {
    // Fill all required fields
    const firstNameInput = page.getByLabel(/first name/i);
    await firstNameInput.fill('Jane');

    const lastNameInput = page.getByLabel(/last name/i);
    await lastNameInput.fill('Smith');

    const emailInput = page.getByPlaceholder(/email/i);
    await emailInput.fill('jane.smith@example.com');

    // Verify submit button is enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).not.toBeDisabled();

    // Clear the email field
    await emailInput.clear();

    // Verify submit button is now disabled again
    await expect(submitButton).toBeDisabled();

    // Fill email again
    await emailInput.fill('jane.smith@example.com');
    await expect(submitButton).not.toBeDisabled();

    // Clear first name field to test edge case
    await firstNameInput.clear();

    // Verify submit button is disabled again
    await expect(submitButton).toBeDisabled();

    // Verify error message does not appear before submission
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).not.toBeVisible();

    // Attempt to find any validation error text
    const validationText = page.getByText(/required field/i);
    const isVisible = await validationText.isVisible().catch(() => false);
    expect(isVisible).toBeFalsy();
  });
});

import { test, expect } from '@playwright/test';

test.describe('Form Auto-Save Draft Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should auto-save form data as draft every 30 seconds', async ({ page }) => {
    // Set up API interception
    await page.route('**/api/drafts/save', (route) => {
      route.continue();
    });

    // Fill form fields using getByLabel/getByRole
    const nameInput = page.getByLabel('Full Name');
    const emailInput = page.getByLabel('Email Address');
    const messageInput = page.getByPlaceholder('Enter your message');

    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');
    await messageInput.fill('This is my test message');

    // Wait for first auto-save (30 seconds)
    const savePromise1 = page.waitForResponse((response) =>
      response.url().includes('/api/drafts/save') && response.status() === 200
    );

    await Promise.race([
      savePromise1,
      new Promise((resolve) => setTimeout(resolve, 35000)),
    ]);

    // Verify draft saved notification
    const draftNotification = page.getByText('Draft saved');
    await expect(draftNotification).toBeVisible();

    // Verify timestamp is present
    const draftTimestamp = page.getByText(/saved at|just now/);
    await expect(draftTimestamp).toBeVisible();

    // Modify form and verify second auto-save
    await messageInput.clear();
    await messageInput.fill('Updated message');

    const savePromise2 = page.waitForResponse((response) =>
      response.url().includes('/api/drafts/save') && response.status() === 200
    );

    await Promise.race([
      savePromise2,
      new Promise((resolve) => setTimeout(resolve, 35000)),
    ]);

    // Verify updated notification
    await expect(draftNotification).toBeVisible();

    // Verify message was saved with new content
    await expect(messageInput).toHaveValue('Updated message');
  });

  test('should handle auto-save failures and display error message', async ({ page }) => {
    // Intercept and fail auto-save requests
    await page.route('**/api/drafts/save', (route) => {
      route.abort('failed');
    });

    // Fill form fields using getByLabel
    const nameInput = page.getByLabel('Full Name');
    const emailInput = page.getByLabel('Email Address');

    await nameInput.fill('Jane Smith');
    await emailInput.fill('jane@example.com');

    // Wait a bit to allow auto-save attempt
    await page.waitForTimeout(32000);

    // Verify error notification appears
    const errorNotification = page.getByText(/Failed to save draft|Error saving/);
    await expect(errorNotification).toBeVisible();

    // Verify form data is retained
    await expect(nameInput).toHaveValue('Jane Smith');
    await expect(emailInput).toHaveValue('jane@example.com');

    // Verify retry button is visible and clickable
    const retryButton = page.getByRole('button', { name: /Retry|Try again/ });
    await expect(retryButton).toBeVisible();

    // Mock successful response for retry
    await page.route('**/api/drafts/save', (route) => {
      route.continue();
    });

    // Click retry button
    await retryButton.click();

    // Wait for successful response
    const savePromise = page.waitForResponse((response) =>
      response.url().includes('/api/drafts/save') && response.status() === 200
    );

    await Promise.race([
      savePromise,
      new Promise((resolve) => setTimeout(resolve, 5000)),
    ]);

    // Verify success notification after retry
    const successNotification = page.getByText('Draft saved');
    await expect(successNotification).toBeVisible();

    // Verify error notification is gone
    await expect(errorNotification).not.toBeVisible();
  });
});

