test.describe('Multi-step Form Progress Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/multi-step-form');
  });

  test('should display progress indicator and update as user progresses through form steps', async ({ page }) => {
    // Verify initial state - Step 1 of 3
    const progressIndicator = page.getByTestId('progress-indicator');
    await expect(progressIndicator).toBeVisible();

    const step1 = page.getByTestId('progress-step-1');
    const step2 = page.getByTestId('progress-step-2');
    const step3 = page.getByTestId('progress-step-3');
    const percentageDisplay = page.getByTestId('progress-percentage');

    await expect(step1).toHaveClass(/active/);
    await expect(step2).not.toHaveClass(/active/);
    await expect(step3).not.toHaveClass(/active/);
    await expect(percentageDisplay).toContainText('33%');

    // Fill first step and proceed
    const firstNameInput = page.getByLabel('First Name');
    const lastNameInput = page.getByLabel('Last Name');
    await firstNameInput.fill('John');
    await lastNameInput.fill('Doe');

    const nextButton = page.getByRole('button', { name: 'Next' });
    await nextButton.click();

    // Verify progress updated to Step 2 of 3
    await expect(step1).toHaveClass(/completed/);
    await expect(step2).toHaveClass(/active/);
    await expect(step3).not.toHaveClass(/active/);
    await expect(percentageDisplay).toContainText('66%');

    // Fill second step and proceed
    const emailInput = page.getByLabel('Email');
    const phoneInput = page.getByLabel('Phone');
    await emailInput.fill('john.doe@example.com');
    await phoneInput.fill('1234567890');
    await nextButton.click();

    // Verify progress updated to Step 3 of 3
    await expect(step1).toHaveClass(/completed/);
    await expect(step2).toHaveClass(/completed/);
    await expect(step3).toHaveClass(/active/);
    await expect(percentageDisplay).toContainText('100%');
  });

  test('should handle navigation back and update progress indicator accordingly', async ({ page }) => {
    // Progress to step 2
    const firstNameInput = page.getByLabel('First Name');
    const lastNameInput = page.getByLabel('Last Name');
    await firstNameInput.fill('Jane');
    await lastNameInput.fill('Smith');

    const nextButton = page.getByRole('button', { name: 'Next' });
    await nextButton.click();

    const step1 = page.getByTestId('progress-step-1');
    const step2 = page.getByTestId('progress-step-2');
    const percentageDisplay = page.getByTestId('progress-percentage');

    await expect(step2).toHaveClass(/active/);

    // Go back to step 1
    const previousButton = page.getByRole('button', { name: 'Previous' });
    await previousButton.click();

    await expect(step1).toHaveClass(/active/);
    await expect(step2).not.toHaveClass(/active/);
    await expect(percentageDisplay).toContainText('33%');

    // Verify form data is preserved
    await expect(firstNameInput).toHaveValue('Jane');
    await expect(lastNameInput).toHaveValue('Smith');

    // Try to click on a previous step directly (edge case)
    await step1.click();
    await expect(step1).toHaveClass(/active/);
    await expect(step2).not.toHaveClass(/active/);
  });
});

