    await expect(navItemLabel).toContainText('Dashboard');

    // Get toggle button using getByRole (mandatory)
    const toggleButton = page.getByRole('button', { name: /toggle|collapse|menu/i });
    await expect(toggleButton).toBeVisible();

    // Click to collapse sidebar
    await toggleButton.click();

    // Verify sidebar is collapsed
    await expect(sidebar).toHaveClass(/collapsed/);
    await expect(sidebarContent).not.toBeVisible();

    // Verify sidebar icons are still visible
    const navIcon = page.locator('[data-testid="nav-icon"]').first();
    await expect(navIcon).toBeVisible();

    // Click again to expand sidebar
    await toggleButton.click();

    // Verify sidebar is expanded again
    const sidebarClass = await sidebar.getAttribute('class');
    expect(sidebarClass).not.toContain('collapsed');
    await expect(sidebarContent).toBeVisible();
    await expect(navItemLabel).toBeVisible();
  });

  test('should persist sidebar state across page navigation - edge case', async ({ page }) => {
    // Get toggle button using getByRole (mandatory)
    const toggleButton = page.getByRole('button', { name: /toggle|collapse|menu/i });
    const sidebar = page.locator('[data-testid="sidebar"]');
    const sidebarContent = page.locator('[data-testid="sidebar-content"]');

