    // Set up listener for navigation API call
    await page.route('/api/dashboard-data', (route) => {
      route.continue();
    });

    // Navigate to settings using getByRole for navigation
    const settingsNav = page.getByRole('link', { name: /settings/i });
    await expect(settingsNav).toBeVisible();
    await settingsNav.click();

    // Wait for navigation to complete
    await page.waitForLoadState('networkidle');

    // Verify sidebar remains collapsed after navigation
    await expect(sidebar).toHaveClass(/collapsed/);
    await expect(sidebarContent).not.toBeVisible();

    // Expand sidebar
    await toggleButton.click();
    const sidebarClassAfterExpand = await sidebar.getAttribute('class');
    expect(sidebarClassAfterExpand).not.toContain('collapsed');

    // Navigate back to dashboard
    const dashboardNav = page.getByRole('link', { name: /dashboard/i });
    await expect(dashboardNav).toBeVisible();
    await dashboardNav.click();

    // Wait for navigation to complete
    await page.waitForLoadState('networkidle');

    // Verify expanded state persists after navigation
    const finalSidebarClass = await sidebar.getAttribute('class');
