test.describe('Internal Links Navigation - Same Tab Opening', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/pages/home');
  });

  test('should open internal links in the same tab without target="_blank"', async ({ page }) => {
    // Verify initial page is visible using getByRole
    const homeHeading = page.getByRole('heading', { name: /home/i });
    await expect(homeHeading).toBeVisible();

    // Find internal navigation link using getByRole
    const aboutLink = page.getByRole('link', { name: /about/i });
    await expect(aboutLink).toBeVisible();

    // Verify link attributes for same-tab behavior
    const hrefValue = await aboutLink.getAttribute('href');
    expect(hrefValue).toBe('/pages/about');

    const targetValue = await aboutLink.getAttribute('target');
    expect(targetValue).toBeNull();

    // Set up listener for page navigation before clicking
    const navigationPromise = page.waitForNavigation();
    await aboutLink.click();

    // Wait for navigation to complete
    await navigationPromise;

    // Verify URL changed and new page content is visible
    expect(page.url()).toContain('/pages/about');
    const aboutHeading = page.getByRole('heading', { name: /about/i });
    await expect(aboutHeading).toBeVisible();

    // Verify browser history allows back navigation (same tab indicator)
    await page.goBack();
    expect(page.url()).toContain('/pages/home');
    await expect(homeHeading).toBeVisible();
  });

  test('should not open external links in same tab and handle edge case of misconfigured internal links', async ({ page }) => {
    // Verify home page loaded using getByRole
    const homeHeading = page.getByRole('heading', { name: /home/i });
    await expect(homeHeading).toBeVisible();

    // Test external link has proper target="_blank" attribute
    const externalLink = page.getByRole('link', { name: /external/i });
    await expect(externalLink).toBeVisible();

    const externalTarget = await externalLink.getAttribute('target');
    expect(externalTarget).toBe('_blank');

    const externalHref = await externalLink.getAttribute('href');
    expect(externalHref).toContain('https://');

    // Test internal link without href using getByText (edge case)
    const brokenLink = page.getByText('Broken Internal Link');
    await expect(brokenLink).toBeVisible();

    const brokenHref = await brokenLink.getAttribute('href');
    expect(brokenHref).toBeNull();

    // Click broken link and verify page doesn't navigate
    await brokenLink.click();
    expect(page.url()).toContain('/pages/home');
    await expect(homeHeading).toBeVisible();

    // Test relative internal link using getByRole
    const relativeLink = page.getByRole('link', { name: /contact/i });
    await expect(relativeLink).toBeVisible();

    const relativeTarget = await relativeLink.getAttribute('target');
    expect(relativeTarget).toBeNull();

    // Navigate using relative link
    const relativeNavPromise = page.waitForNavigation();
    await relativeLink.click();
    await relativeNavPromise;

    // Verify same tab behavior with relative paths
    expect(page.url()).not.toContain('_blank');
  });
});

import { test, expect } from '@playwright/test';

test.describe('External Links Open in New Tab', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('Happy path: external link opens in new tab with target="_blank"', async ({ page, context }) => {
    // Get and verify external link element by role
    const externalLinkGithub = page.getByRole('link', { name: 'Visit GitHub' });
    await expect(externalLinkGithub).toBeVisible();

    // Verify external link has correct href
    await expect(externalLinkGithub).toHaveAttribute('href', 'https://github.com');

    // Verify target="_blank" attribute
    await expect(externalLinkGithub).toHaveAttribute('target', '_blank');

    // Verify rel attribute for security
    await expect(externalLinkGithub).toHaveAttribute('rel', 'noopener noreferrer');

    // Get Twitter external link by role
    const externalLinkTwitter = page.getByRole('link', { name: 'Follow Twitter' });
    await expect(externalLinkTwitter).toBeVisible();
    await expect(externalLinkTwitter).toHaveAttribute('target', '_blank');
    await expect(externalLinkTwitter).toHaveAttribute('rel', 'noopener noreferrer');

    // Verify current page URL remains unchanged after interacting with page
    const initialUrl = page.url();
    await externalLinkGithub.click();

    // Wait briefly to ensure navigation doesn't occur
    await page.waitForTimeout(500);
    expect(page.url()).toBe(initialUrl);

    // Verify page heading is still visible (page didn't navigate)
    const pageHeading = page.getByRole('heading', { name: 'Home' });
    await expect(pageHeading).toBeVisible();
  });

  test('Negative case: internal links do NOT open in new tab', async ({ page }) => {
    // Get internal link by role
    const internalLinkAbout = page.getByRole('link', { name: 'About Us' });
    await expect(internalLinkAbout).toBeVisible();

    // Verify internal link does NOT have target="_blank"
    const targetAttr = await internalLinkAbout.getAttribute('target');
    expect(targetAttr).not.toBe('_blank');

    // Verify internal link href is relative
    await expect(internalLinkAbout).toHaveAttribute('href', '/about');

    // Verify internal link does not have noopener rel
    const relAttr = await internalLinkAbout.getAttribute('rel');
    expect(relAttr).not.toContain('noopener noreferrer');

    // Click internal link and verify navigation
    await internalLinkAbout.click();
    await page.waitForURL('**/about');
    expect(page.url()).toContain('/about');

    // Verify page navigated by checking heading
    const aboutHeading = page.getByRole('heading', { name: 'About' });
    await expect(aboutHeading).toBeVisible();

    // Go back and verify contact link also doesn't open in new tab
    await page.goto('/');
    const internalLinkContact = page.getByRole('link', { name: 'Contact Us' });
    await expect(internalLinkContact).toBeVisible();

    const contactTargetAttr = await internalLinkContact.getAttribute('target');
    expect(contactTargetAttr).not.toBe('_blank');
  });
});

