    const headerStyles = await header.evaluate((el) => window.getComputedStyle(el).position);
    expect(headerStyles).toBe('sticky');

    // Scroll down the page
    await page.evaluate(() => window.scrollBy(0, 500));

    // Header should still be visible after scrolling
    await expect(header).toBeVisible();

    // Navigation links should remain accessible
    await expect(homeLink).toBeVisible();
    await expect(aboutLink).toBeVisible();

    // Verify header position is at top
