import { test, expect } from '@playwright/test';

test.describe('Dropdown Navigation with Arrow Keys', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dropdown-menu');
  });

  test('should navigate dropdown items using arrow keys and select with Enter', async ({ page }) => {
    // Open the dropdown menu
    const dropdownTrigger = page.getByRole('button', { name: /open menu/i });
    await dropdownTrigger.click();

    const dropdownMenu = page.getByRole('listbox');
    await expect(dropdownMenu).toBeVisible();

    // First item should be focused by default
    const firstItem = page.getByRole('option', { name: /option 1/i });
    await expect(firstItem).toHaveAttribute('aria-selected', 'true');

    // Navigate down to second item
    await dropdownMenu.press('ArrowDown');
    const secondItem = page.getByRole('option', { name: /option 2/i });
    await expect(secondItem).toHaveAttribute('aria-selected', 'true');
    await expect(firstItem).not.toHaveAttribute('aria-selected', 'true');

    // Navigate down to third item
    await dropdownMenu.press('ArrowDown');
    const thirdItem = page.getByRole('option', { name: /option 3/i });
    await expect(thirdItem).toHaveAttribute('aria-selected', 'true');

    // Navigate back up to second item
    await dropdownMenu.press('ArrowUp');
    await expect(secondItem).toHaveAttribute('aria-selected', 'true');
    await expect(thirdItem).not.toHaveAttribute('aria-selected', 'true');

    // Select the focused item with Enter
    await dropdownMenu.press('Enter');
    const selectedValue = page.getByTestId('dropdown-selected-value');
    await expect(selectedValue).toContainText('Option 2');
    await expect(dropdownMenu).not.toBeVisible();
  });

  test('should handle edge cases - wrap around and disabled items', async ({ page }) => {
    // Open the dropdown
    const dropdownTrigger = page.getByRole('button', { name: /open menu/i });
    await dropdownTrigger.click();

    const dropdownMenu = page.getByRole('listbox');
    await expect(dropdownMenu).toBeVisible();

    // Navigate to last item (4 down arrows from start)
    await dropdownMenu.press('ArrowDown');
    await dropdownMenu.press('ArrowDown');
    await dropdownMenu.press('ArrowDown');
    await dropdownMenu.press('ArrowDown');
    const lastItem = page.getByRole('option', { name: /option 5/i });
    await expect(lastItem).toHaveAttribute('aria-selected', 'true');

    // Press down arrow again - should wrap to first item
    await dropdownMenu.press('ArrowDown');
    const firstItem = page.getByRole('option', { name: /option 1/i });
    await expect(firstItem).toHaveAttribute('aria-selected', 'true');

    // Press up arrow - should wrap to last item
    await dropdownMenu.press('ArrowUp');
    await expect(lastItem).toHaveAttribute('aria-selected', 'true');

    // Test disabled item - navigate to item 4 which is disabled
    await dropdownMenu.press('ArrowUp');
    await dropdownMenu.press('ArrowUp');
    const thirdItem = page.getByRole('option', { name: /option 3/i });
    await expect(thirdItem).toHaveAttribute('aria-selected', 'true');

    // Verify disabled item exists
    const disabledItem = page.getByRole('option', { name: /option 4/i });
    await expect(disabledItem).toBeDisabled();

    // Select the current focused item with Enter
    await dropdownMenu.press('Enter');
    const selectedValue = page.getByTestId('dropdown-selected-value');
    await expect(selectedValue).toContainText('Option 3');
    await expect(dropdownMenu).not.toBeVisible();
  });
});

