test.describe('Optimistic UI Updates - Like Post Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/posts');

    await page.route('GET /api/posts', async (route) => {
      await route.fulfill({
        status: 200,
        body: JSON.stringify([
          {
            id: 1,
            title: 'Test Post',
            content: 'This is a test post',
            likes: 41,
            liked: false
          }
        ])
      });
    });

    await page.route('POST /api/posts/*/likes', async (route) => {
      await route.fulfill({
        status: 200,
        body: JSON.stringify({ success: true, likes: 42 })
      });
    });

    await page.waitForLoadState('networkidle');
  });

  test('should show optimistic UI update when liking a post and confirm with API response', async ({ page }) => {
    const postCard = page.getByTestId('post-1');
    await expect(postCard).toBeVisible();

    const likeButton = page.getByRole('button', { name: /like/i });
    await expect(likeButton).toBeVisible();
    await expect(likeButton).toContainText('41');

    const likeIcon = page.getByTestId('like-icon-1');
    await expect(likeIcon).toHaveAttribute('aria-label', 'Like');

    // User clicks like button - optimistic update happens immediately
    await likeButton.click();

    // Verify optimistic UI update before API response confirms
    await expect(likeButton).toContainText('42');
    const updatedLikeIcon = page.getByTestId('like-icon-1');
    await expect(updatedLikeIcon).toHaveAttribute('aria-label', 'Unlike');

    // Wait for network to settle
    await page.waitForLoadState('networkidle');

    // Verify state persists after API response
    await expect(likeButton).toContainText('42');
    await expect(updatedLikeIcon).toHaveAttribute('aria-label', 'Unlike');
