    await likeButton.click();
    await expect(likeButton).toContainText('42');

    // Wait for API failure to be processed
    await page.waitForLoadState('networkidle');

    // Verify rollback to original state
    await expect(likeButton).toContainText('41');
    await expect(errorMessage).toBeVisible();

    // Verify like icon reverts
    const likeIcon = page.getByTestId('like-icon-1');
    await expect(likeIcon).toHaveAttribute('aria-label', 'Like');
  });
});

