test.describe('Stale Data Invalidation After Form Submission', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page');
  });

  test('should invalidate stale data after successful form submission', async ({ page }) => {
    // Intercept initial data fetch
    await page.route('/api/user-data', (route) => {
      route.continue();
    });

    // Verify initial stale data is displayed
    const userName = page.getByRole('heading', { name: /John Doe/i });
    await expect(userName).toBeVisible();
    const userEmail = page.getByText('john@example.com');
    await expect(userEmail).toBeVisible();

    // Fill form with new data
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('Jane Smith');
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('jane@example.com');

    // Setup route to intercept form submission
    let submissionSucceeded = false;
    await page.route('/api/update-user', (route) => {
      submissionSucceeded = true;
      route.continue();
    });

    // Submit form
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify submission was successful
    await page.waitForTimeout(500);
    expect(submissionSucceeded).toBe(true);

    // Verify stale data has been invalidated and updated
    const updatedName = page.getByRole('heading', { name: /Jane Smith/i });
    await expect(updatedName).toBeVisible();
    const updatedEmail = page.getByText('jane@example.com');
    await expect(updatedEmail).toBeVisible();
    const successMessage = page.getByText('Data updated successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should not invalidate stale data when form submission fails', async ({ page }) => {
    // Intercept initial data fetch
    await page.route('/api/user-data', (route) => {
      route.continue();
    });

    // Verify initial stale data is displayed
    const userName = page.getByRole('heading', { name: /John Doe/i });
    await expect(userName).toBeVisible();
    const userEmail = page.getByText('john@example.com');
    await expect(userEmail).toBeVisible();

    // Fill form with invalid data
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('');
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('invalid-email');

    // Setup route to intercept failed form submission
    await page.route('/api/update-user', (route) => {
      route.abort('failed');
    });

    // Attempt to submit form
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify error message is displayed
    await page.waitForTimeout(300);
    const errorMessage = page.getByText(/validation failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify stale data remains unchanged (NOT invalidated)
    const unChangedName = page.getByRole('heading', { name: /John Doe/i });
    await expect(unChangedName).toBeVisible();
    const unChangedEmail = page.getByText('john@example.com');
    await expect(unChangedEmail).toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText('Data updated successfully');
    await expect(successMessage).not.toBeVisible();
