import { test, expect } from '@playwright/test';

test.describe('Search Results with Debounced Updates', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
    // Setup intercept for API calls
    await page.route('/api/search?q=*', route => {
      route.continue();
    });
  });

  test('should debounce search queries by 300ms and update results as user types', async ({ page }) => {
    // Arrange
    const searchInput = page.getByRole('textbox', { name: /search/i });
    const searchButton = page.getByRole('button', { name: /search/i });

    await expect(searchInput).toBeVisible();

    // Act - Setup request listener before typing
    const requestPromise = page.waitForResponse(response =>
      response.url().includes('/api/search') && response.status() === 200
    );

    // Type characters with timing to test debounce
    await searchInput.fill('j');
    await page.waitForTimeout(150);

    // Type more characters
    await searchInput.fill('ja');
    await page.waitForTimeout(150);

    await searchInput.fill('jav');

    // Wait for debounce to complete and API response
    const response = await requestPromise;
    expect(response.url()).toContain('q=jav');

    // Assert - Results are displayed
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();

    const resultItems = page.getByTestId('result-item');
    const itemCount = await resultItems.count();
    expect(itemCount).toBeGreaterThan(0);

    // Assert - First result contains expected text
    await expect(resultItems.first()).toContainText('Java');
  });

  test('should handle empty search input and show no results message', async ({ page }) => {
    // Arrange
    const searchInput = page.getByRole('textbox', { name: /search/i });
    const emptyStateMessage = page.getByText(/no results found/i);

    await expect(searchInput).toBeVisible();

    // Act - Setup request listener
    const requestPromise = page.waitForResponse(response =>
      response.url().includes('/api/search') && response.status() === 200
    );

    // Type and then clear the input
    await searchInput.fill('test');
    await searchInput.clear();

    // Wait for debounce and API response
    const response = await requestPromise;
    expect(response.url()).toContain('q=');

    // Assert - Empty state message is visible
    await expect(emptyStateMessage).toBeVisible();

    // Assert - No results are displayed
    const resultItems = page.getByTestId('result-item');
    const itemCount = await resultItems.count();
    expect(itemCount).toBe(0);
  });
});

