test.describe('Polling stops when navigating away from page', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/polling-dashboard');
  });

  test('should stop polling API calls when user navigates to a different page', async ({ page }) => {
    // Setup: Intercept polling API endpoint
    let pollingRequestCount = 0;
    await page.route('**/api/polling/data', (route) => {
      pollingRequestCount++;
      route.continue();
    });

    // Verify initial page is loaded
    const pollingStatus = page.getByTestId('polling-status');
    await expect(pollingStatus).toBeVisible();

    // Wait for polling requests to begin
    await page.waitForTimeout(500);
    const initialCount = pollingRequestCount;
    expect(initialCount).toBeGreaterThan(0);

    // Wait for additional polling requests to confirm active polling
    await page.waitForTimeout(1000);
    const activeCount = pollingRequestCount;
    expect(activeCount).toBeGreaterThan(initialCount);

    // Verify polling indicator shows active status
    const pollingIndicator = page.getByTestId('polling-indicator');
    await expect(pollingIndicator).toContainText('Active');

    // Navigate away from the page using button
    const homeButton = page.getByRole('button', { name: /home/i });
    await expect(homeButton).toBeVisible();
    await homeButton.click();

    // Verify navigation occurred
    await expect(page).toHaveURL(/\/home/);

    // Record polling count before waiting
    const countBeforeWait = pollingRequestCount;

    // Wait to ensure polling would have made additional requests
    await page.waitForTimeout(2000);

    // Verify no additional polling requests were made after navigation
    expect(pollingRequestCount).toBe(countBeforeWait);
  });

  test('should handle rapid navigation without memory leaks or lingering requests', async ({ page }) => {
    // Setup: Track polling requests
    let pollingRequestCount = 0;
    await page.route('**/api/polling/data', (route) => {
      pollingRequestCount++;
      route.continue();
    });

    // Wait for initial polling to start
    await page.waitForTimeout(500);
    const initialCount = pollingRequestCount;
    expect(initialCount).toBeGreaterThan(0);

    // Rapidly navigate to multiple pages using role-based selectors
    const profileButton = page.getByRole('button', { name: /profile/i });
    await expect(profileButton).toBeVisible();
    await profileButton.click();
    await expect(page).toHaveURL(/\/profile/);

    const settingsButton = page.getByRole('button', { name: /settings/i });
    await expect(settingsButton).toBeVisible();
    await settingsButton.click();
    await expect(page).toHaveURL(/\/settings/);

    const dashboardButton = page.getByRole('button', { name: /dashboard/i });
    await expect(dashboardButton).toBeVisible();
    await dashboardButton.click();
    await expect(page).toHaveURL(/\/dashboard/);

    // Return to original polling page
    await page.goto('/polling-dashboard');

    // Reset request counter for fresh polling session
    pollingRequestCount = 0;

    // Verify polling restarts cleanly
    const pollingStatus = page.getByTestId('polling-status');
    await expect(pollingStatus).toBeVisible();

    const pollingIndicator = page.getByTestId('polling-indicator');
    await expect(pollingIndicator).toContainText('Active');

    // Verify new polling requests are being made
    await page.waitForTimeout(1000);
    expect(pollingRequestCount).toBeGreaterThan(0);

    // Verify data is being updated correctly
    const pollingData = page.getByTestId('polling-data');
    await expect(pollingData).not.toBeEmpty();
  });
});

