import { test, expect } from '@playwright/test';

test.describe('API Response Caching - Instant Repeat Visits', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should cache API responses and load instantly on repeat visits', async ({ page }) => {
    // Set up route interception for first visit
    await page.route('**/api/user/profile', async (route) => {
      await route.continue();
    });

    // First visit - API call should be made
    const loadProfileButton = page.getByRole('button', { name: /load profile/i });
    await loadProfileButton.click();

    // Wait for response and verify initial data
    const profileName = page.getByText(/John Doe/);
    await expect(profileName).toBeVisible();

    const profileEmail = page.getByLabel(/email/i);
    await expect(profileEmail).toHaveValue('john@example.com');

    // Record initial load timestamp
    const initialTime = Date.now();

    // Navigate away and return to test caching behavior
    await page.goto('/settings');
    await page.goto('/dashboard');

    // Set up route to verify cache is used (no actual network request)
    let networkRequestMade = false;
    await page.route('**/api/user/profile', async (route) => {
      networkRequestMade = true;
      await route.abort();
    });

    // Second visit - should use cache
    const reloadButton = page.getByRole('button', { name: /load profile/i });
    await reloadButton.click();

    // Verify cached data appears instantly
    await expect(profileName).toBeVisible();
    const cacheIndicator = page.getByText(/loaded from cache/i);
    await expect(cacheIndicator).toBeVisible();

    // Verify load time is minimal (under 100ms)
    const finalTime = Date.now();
    expect(finalTime - initialTime).toBeLessThan(100);

    // Verify no new network request was made
    expect(networkRequestMade).toBeFalsy();
  });

  test('should invalidate cache when refresh is triggered or cache expires', async ({ page }) => {
    // First API call to establish cache
    await page.route('**/api/user/profile', async (route) => {
      await route.continue();
    });

    const loadButton = page.getByRole('button', { name: /load profile/i });
    await loadButton.click();

    const profileName = page.getByText(/John Doe/);
    await expect(profileName).toBeVisible();

    // Set up fresh data response for cache invalidation
    await page.route('**/api/user/profile', async (route) => {
      await route.fulfill({
        status: 200,
        body: JSON.stringify({ name: 'Jane Doe', email: 'jane@example.com' })
      });
    });

    // Trigger cache refresh
    const refreshButton = page.getByRole('button', { name: /refresh cache/i });
    await refreshButton.click();

    // Verify fresh data is loaded
    const updatedName = page.getByText(/Jane Doe/);
    await expect(updatedName).toBeVisible();

    // Verify cache status indicator shows cleared state
    const cacheStatus = page.getByText(/cache cleared/i);
    await expect(cacheStatus).toBeVisible();

    // Verify cache indicator is not shown for fresh data
    const cacheIndicator = page.getByText(/loaded from cache/i);
    await expect(cacheIndicator).not.toBeVisible();

    // Simulate cache expiration by waiting
    await page.waitForTimeout(3600000);

    // Next request should bypass cache and fetch fresh data
    let freshRequestMade = false;
    await page.route('**/api/user/profile', async (route) => {
      freshRequestMade = true;
      await route.continue();
    });

    await loadButton.click();
    expect(freshRequestMade).toBeTruthy();

    // Verify no cache indicator for expired cache
    await expect(cacheIndicator).not.toBeVisible();
  });
