import { test, expect } from '@playwright/test';

test.describe('Stale Record Conflict Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display conflict error message when saving a stale record', async ({ page }) => {
    // Setup: intercept the initial GET request for a record
    await page.route('**/api/records/123', route => {
      route.abort();
    });

    // Open a record using getByRole
    const recordButton = page.getByRole('button', { name: /record-item-123/i });
    await recordButton.click();

    // Setup: intercept the PUT request with a conflict response
    await page.route('**/api/records/123', route => {
      if (route.request().method() === 'PUT') {
        route.abort('failed');
      }
    });

    // Wait for record to load, then modify field using getByLabel
    const nameInput = page.getByLabel(/record.*name/i);
    await nameInput.fill('Updated Name');

    // Intercept save with conflict response
    await page.route('**/api/records/123', async route => {
      if (route.request().method() === 'PUT') {
        await route.abort();
      }
    });

    // Actually set up proper interceptor
    await page.route('**/api/records/123', route => {
      if (route.request().method() === 'PUT') {
        route.fulfill({
          status: 409,
          body: JSON.stringify({
            error: 'Conflict: Record has been modified by another user',
            currentVersion: 2,
            yourVersion: 1
          })
        });
      }
    });

    // User attempts to save using getByRole
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Wait for error response
    await page.waitForResponse(response => response.status() === 409);

    // Verify conflict error message is displayed
    const errorMessage = page.getByText(/Conflict: Record has been modified/);
    await expect(errorMessage).toBeVisible();

    // Verify save button is disabled after error
    await expect(saveButton).toBeDisabled();
  });

  test('should handle successful save after resolving conflict', async ({ page }) => {
    // Setup: intercept initial GET
    await page.route('**/api/records/456', route => {
      if (route.request().method() === 'GET') {
        route.fulfill({
          status: 200,
          body: JSON.stringify({ id: 456, name: 'Test', version: 1 })
        });
      }
    });

    // Navigate to record
    const recordLink = page.getByRole('link', { name: /record.*456/i });
    await recordLink.click();

    // First save attempt fails with 409
    let attemptCount = 0;
    await page.route('**/api/records/456', route => {
      if (route.request().method() === 'PUT') {
        attemptCount++;
        if (attemptCount === 1) {
          route.fulfill({
            status: 409,
            body: JSON.stringify({
              error: 'Conflict: Record has been modified',
              currentVersion: 3,
              yourVersion: 1
            })
          });
        } else {
          route.fulfill({
            status: 200,
            body: JSON.stringify({
              id: 456,
              version: 3,
              message: 'Record saved successfully'
            })
          });
        }
      }
    });

    // Modify field using getByLabel
    const descriptionInput = page.getByLabel(/description/i);
    await descriptionInput.fill('New Description');

    // First save attempt
    const saveBtn = page.getByRole('button', { name: /save/i });
    await saveBtn.click();

    // Wait for conflict response
    await page.waitForResponse(response => response.status() === 409);

    // Verify error message appears
    const errorMsg = page.getByText(/Conflict/);
    await expect(errorMsg).toBeVisible();

    // User clicks reload button to refresh
    const reloadButton = page.getByRole('button', { name: /reload|refresh/i });
    await reloadButton.click();

    // Wait for reload
    await page.waitForResponse(response => 
      response.url().includes('/records/456') && response.status() === 200
    );

    // Second save attempt (should succeed)
    await saveBtn.click();

    // Wait for success response
    await page.waitForResponse(response => 
      response.url().includes('/records/456') && response.status() === 200
    );

    // Verify success message
    const successMsg = page.getByText(/Record saved successfully/);
    await expect(successMsg).toBeVisible();
  });
});

