    await expect(modifiedDateLocator).toBeVisible();
    const modifiedDateText = await modifiedDateLocator.textContent();
    expect(modifiedDateText).toContain(new Date().getFullYear().toString());

    // Verify date format matches expected pattern
    const datePattern = /[A-Z][a-z]{2}\s\d{1,2},\s\d{4}/;
    expect(createdDateText).toMatch(datePattern);
    expect(modifiedDateText).toMatch(datePattern);

    // Verify created and modified dates are the same on new record
    expect(createdDateText).toBe(modifiedDateText);
  });

  test('should update last modified date when record is edited', async ({ page }) => {
    // Navigate to an existing record
    const recordItem = page.locator('[data-testid="record-item"]').first();
    await recordItem.click();
    await page.waitForLoadState('networkidle');

    // Capture original dates
    const createdDateLocator = page.locator('[data-testid="record-created-date"]');
    const originalCreatedDate = await createdDateLocator.textContent();

    const modifiedDateLocator = page.locator('[data-testid="record-modified-date"]');
    const originalModifiedDate = await modifiedDateLocator.textContent();

    // Edit the record
    const editBtn = page.getByRole('button', { name: /edit/i });
    await expect(editBtn).toBeVisible();
    await editBtn.click();

    const nameInput = page.getByLabel(/record name/i);
