    await page.waitForLoadState('networkidle');

    // Verify created date hasn't changed
    const updatedCreatedDate = await createdDateLocator.textContent();
    expect(updatedCreatedDate).toBe(originalCreatedDate);

    // Verify last modified date has changed
    const updatedModifiedDate = await modifiedDateLocator.textContent();
    expect(updatedModifiedDate).not.toBe(originalModifiedDate);

    // Verify modified date contains current year
    expect(updatedModifiedDate).toContain(new Date().getFullYear().toString());
  });
});

