test.describe('Request Timeout Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/request-page');
  });

  test('should display timeout error when request exceeds 10 seconds', async ({ page }) => {
    // Route the slow endpoint with extended delay
    await page.route('/api/data/slow', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 11000)); // 11 seconds
      await route.abort('timedout');
    });

    // Click the fetch button using getByRole
    const fetchButton = page.getByRole('button', { name: /fetch slow data/i });
    await expect(fetchButton).toBeVisible();
    await fetchButton.click();

    // Wait for timeout error and verify it's displayed
    const errorMessage = page.getByText(/request timeout|request timed out/i);
    await expect(errorMessage).toBeVisible();

    // Verify error icon is displayed using getByRole
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify loading spinner is hidden
    const loadingSpinner = page.locator('[data-testid="loading-spinner"]');
    await expect(loadingSpinner).not.toBeVisible();

    // Verify retry button appears
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
  });

  test('should handle multiple timeout errors and allow successful retry', async ({ page }) => {
    // First request - timeout
    await page.route('/api/data/slow', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 11000));
      await route.abort('timedout');
    });

    // Trigger initial request using getByRole
    const fetchButton = page.getByRole('button', { name: /fetch slow data/i });
    await fetchButton.click();

    // Verify timeout error appears
    const errorMessage = page.getByText(/request timeout|request timed out/i);
    await expect(errorMessage).toBeVisible();

    // Unroute previous route and setup successful response
    await page.unroute('/api/data/slow');
    await page.route('/api/data/slow', async (route) => {
      await route.continue();
    });

    // Mock successful response
    await page.route('/api/data/slow', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ data: 'success', timestamp: Date.now() })
      });
    });

    // Click retry button using getByRole
    const retryButton = page.getByRole('button', { name: /retry/i });
    await retryButton.click();

    // Verify error is cleared
    await expect(errorMessage).not.toBeVisible();

    // Verify success data is displayed
    const successData = page.getByText(/success/i);
    await expect(successData).toBeVisible();

    // Verify data container is visible
    const dataDisplay = page.locator('[data-testid="data-display"]');
    await expect(dataDisplay).toBeVisible();
  });
});

