test.describe('Rate Limit Error on Form Submission', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/contact-form');
  });

  test('should display rate-limit error after exceeding submission threshold', async ({ page }) => {
    let submissionCount = 0;

    // Mock API endpoint with rate limit logic
    await page.route('**/api/contact', async (route) => {
      submissionCount++;
      if (submissionCount > 5) {
        await route.abort('blockedbyclient');
        // Manually trigger error handling
        const error = {
          status: 429,
          statusText: 'Too Many Requests',
          body: {
            error: 'Too Many Requests',
            message: 'Rate limit exceeded. Please try again in 60 seconds.',
            retryAfter: 60
          }
        };
        await route.fulfill({ status: 429, body: JSON.stringify(error.body) });
      } else {
        await route.fulfill({
          status: 200,
          body: JSON.stringify({ success: true, message: 'Form submitted successfully' })
        });
      }
    });

    // Submit form multiple times
    for (let i = 0; i < 6; i++) {
      const nameInput = page.getByLabel('Full Name');
      const emailInput = page.getByLabel('Email Address');
      const submitButton = page.getByRole('button', { name: /submit/i });

      await nameInput.fill(`User ${i}`);
      await emailInput.fill(`user${i}@example.com`);
      await submitButton.click();

      // Small delay for network request
      await page.waitForTimeout(500);

      if (i < 5) {
        const successMessage = page.getByText('Form submitted successfully');
        await expect(successMessage).toBeVisible();
      } else {
        const errorMessage = page.getByText(/rate limit exceeded/i);
        await expect(errorMessage).toBeVisible();
        const retryMessage = page.getByText(/try again in 60 seconds/i);
        await expect(retryMessage).toBeVisible();
      }
    }

    // Verify submit button is disabled after rate limit
    const submitBtn = page.getByRole('button', { name: /submit/i });
    await expect(submitBtn).toBeDisabled();
  });

  test('should handle 429 error gracefully with retry countdown', async ({ page }) => {
    // Intercept all POST requests to /api/contact with 429 response
    await page.route('**/api/contact', async (route) => {
      await route.fulfill({
        status: 429,
        contentType: 'application/json',
        body: JSON.stringify({
          error: 'Too Many Requests',
          message: 'Rate limit exceeded. Please try again in 60 seconds.',
          retryAfter: 60
        })
      });
    });

    // Locate and fill form using accessible selectors
    const nameInput = page.getByLabel('Full Name');
    const emailInput = page.getByLabel('Email Address');
    const submitButton = page.getByRole('button', { name: /submit/i });

    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');
    await submitButton.click();

    // Wait for error response
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByText(/too many requests/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry message with timeframe
    const retryMessage = page.getByText(/rate limit exceeded/i);
    await expect(retryMessage).toBeVisible();

    // Verify submit button is disabled during cooldown
    const submitBtn = page.getByRole('button', { name: /submit/i });
    await expect(submitBtn).toBeDisabled();

    // Verify error container has error class styling
    const errorContainer = page.locator('[data-testid="error-container"]');
    await expect(errorContainer).toHaveClass(/error-state/);

    // Verify countdown timer is displayed and contains numeric value
    const timerDisplay = page.getByText(/60 seconds/i);
    await expect(timerDisplay).toBeVisible();
  });
});

