    await expect(errorBoundary).toBeVisible();

    const errorMessage = page.getByText(/something went wrong/i);
    await expect(errorMessage).toBeVisible();

    // Verify recovery button is available and clickable
    const recoveryButton = page.getByRole('button', { name: /recover/i });
    await expect(recoveryButton).toBeVisible();
    await expect(recoveryButton).toBeEnabled();

    // Set up intercept for recovery API call
    await page.route('**/api/recover', route => {
      route.abort();
      setTimeout(() => route.continue(), 100);
    });

    // Click recovery button
    await recoveryButton.click();

    // Wait for recovery
    await page.waitForTimeout(600);

    // Verify app recovered to initial state
    await expect(errorBoundary).not.toBeVisible();

    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(mainContent).toContainText('Welcome');
  });

  test('should handle unrecoverable errors and show fallback UI', async ({ page }) => {
    // Navigate to page with known unrecoverable error
    await page.goto('/?error=unrecoverable');

    // Verify critical error boundary is displayed
    const criticalError = page.locator('[data-testid="critical-error-boundary"]');
    await expect(criticalError).toBeVisible();

    const errorMsg = page.getByText(/critical error/i);
    await expect(errorMsg).toBeVisible();

    // Verify fallback UI is shown
    const fallbackUI = page.locator('[data-testid="fallback-ui"]');
    await expect(fallbackUI).toBeVisible();

    const supportContact = page.getByText(/support@example.com/i);
    await expect(supportContact).toBeVisible();

    // Verify recovery button is disabled or does not exist for unrecoverable errors
    const recoveryBtn = page.getByRole('button', { name: /recover/i });
    const exists = await recoveryBtn.isVisible().catch(() => false);

    if (exists) {
      await expect(recoveryBtn).toBeDisabled();
    } else {
      await expect(recoveryBtn).not.toBeVisible();
    }

    // Verify page structure is still intact
    const header = page.getByRole('banner');
    await expect(header).toBeVisible();

