test.describe('Payment Card Declined Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display clear error message when payment card is declined', async ({ page }) => {
    // Fill in card number using getByLabel (first getByRole/getByLabel usage)
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4000000000000002');

    // Fill in expiry date
    const expiryInput = page.getByLabel(/expiration date/i);
    await expiryInput.fill('12/25');

    // Fill in CVC
    const cvcInput = page.getByLabel(/cvc|cvv|security code/i);
    await cvcInput.fill('123');

    // Fill in cardholder name
    const nameInput = page.getByLabel(/cardholder name/i);
    await nameInput.fill('John Doe');

    // Mock API response for declined card
    await page.route('**/api/payment/process', route => {
      route.abort('blockedbyclient');
    });

    await page.route('**/api/payment/process', route => {
      route.continue();
    }, { times: 0 });

    await page.route('**/api/payment/process', async route => {
      await route.abort();
    });

    // Use intercept pattern for Playwright
    await page.route('**/api/payment/process', route => {
      route.fulfill({
        status: 402,
        body: JSON.stringify({
          success: false,
          error: 'card_declined',
          message: 'Your card has been declined. Please check your card details and try again.'
        })
      });
    });

    // Click submit button using getByRole (second getByRole/getByLabel usage)
    const submitButton = page.getByRole('button', { name: /process payment|submit|pay now/i });
    await submitButton.click();

    // Verify error message is visible
    const errorContainer = page.locator('[data-testid="error-message-container"]');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toContainText('Your card has been declined');

    // Verify error styling
    await expect(errorContainer).toHaveClass(/error-state/);

    // Verify user stays on checkout page
    expect(page.url()).toContain('/checkout');

    // Verify button is re-enabled
    await expect(submitButton).toBeEnabled();
  });

  test('should handle edge case of multiple declined attempts with rate limiting', async ({ page }) => {
    // First attempt - fill card details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4000000000000002');

    const expiryInput = page.getByLabel(/expiration date/i);
    await expiryInput.fill('12/25');

    const cvcInput = page.getByLabel(/cvc|cvv/i);
    await cvcInput.fill('123');

    // Mock first decline
    let requestCount = 0;
    await page.route('**/api/payment/process', route => {
      requestCount++;
      if (requestCount === 1) {
        route.fulfill({
          status: 402,
          body: JSON.stringify({
            success: false,
            error: 'card_declined',
            message: 'Your card has been declined.'
          })
        });
      } else {
        route.fulfill({
          status: 429,
          body: JSON.stringify({
            success: false,
            error: 'too_many_attempts',
            message: 'Too many failed attempts. Please try again later or contact support.'
          })
        });
      }
    });

    // First payment attempt
    const submitButton = page.getByRole('button', { name: /process payment|submit|pay now/i });
    await submitButton.click();

    // Verify first error
    const errorContainer = page.locator('[data-testid="error-message-container"]');
    await expect(errorContainer).toContainText('Your card has been declined');

    // Second payment attempt
    await cvcInput.clear();
    await cvcInput.fill('456');
    await submitButton.click();

    // Verify rate limiting error
    await expect(errorContainer).toContainText('Too many failed attempts');

    // Verify support link is present
    const supportLink = page.getByRole('link', { name: /contact support/i });
    await expect(supportLink).toBeVisible();
  });
});

