    const proceedToPaymentButton = page.getByRole('button', { name: /proceed to payment/i });
    await expect(proceedToPaymentButton).toBeDisabled();

    // Step 5: Attempt to retry and succeed
    await page.unroute('/api/shipping/rates');
    await retryButton.click();
    await page.waitForResponse(response => response.url().includes('/api/shipping/rates') && response.status() === 200);
    await expect(page.getByTestId('shipping-options')).toBeVisible();
    await expect(page.getByTestId('error-banner')).not.toBeVisible();
  });
});

