import { test, expect } from '@playwright/test';

test.describe('Modal Content Independent Scrolling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-scroll-test');
  });

  test('should allow modal content to scroll independently when overflow occurs', async ({ page }) => {
    // Open modal with overflowing content
    const openBtn = page.getByRole('button', { name: /open modal/i });
    await openBtn.click();

    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Get modal content scrollable container
    const scrollableContent = page.locator('[data-testid="modal-content-scrollable"]');
    await expect(scrollableContent).toBeVisible();

    // Verify content overflows
    const scrollHeight = await scrollableContent.evaluate((el) => el.scrollHeight);
    const clientHeight = await scrollableContent.evaluate((el) => el.clientHeight);
    expect(scrollHeight).toBeGreaterThan(clientHeight);

    // Get initial scroll position
    const initialScrollTop = await scrollableContent.evaluate((el) => el.scrollTop);
    expect(initialScrollTop).toBe(0);

    // Scroll within modal content
    await scrollableContent.evaluate((el) => {
      el.scrollTop = 300;
    });

    // Verify scroll position changed within modal
    const scrolledPosition = await scrollableContent.evaluate((el) => el.scrollTop);
    expect(scrolledPosition).toBe(300);

    // Verify page scroll did not change
    const pageScrollY = await page.evaluate(() => window.scrollY);
    expect(pageScrollY).toBe(0);

    // Verify modal header is still visible
    const header = page.getByRole('heading', { name: /modal title/i });
    await expect(header).toBeVisible();

    // Verify close button is visible and functional
    const closeBtn = page.getByRole('button', { name: /close|×/i });
    await expect(closeBtn).toBeVisible();
    await closeBtn.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();
  });

  test('should handle edge case when modal content does not overflow', async ({ page }) => {
    // Open modal with non-overflowing content
    const openSmallBtn = page.getByRole('button', { name: /open small modal/i });
    await openSmallBtn.click();

    const smallModal = page.getByRole('dialog');
    await expect(smallModal).toBeVisible();

    // Get modal content scrollable container
    const scrollableSmallContent = page.locator('[data-testid="modal-content-scrollable-small"]');
    await expect(scrollableSmallContent).toBeVisible();

    // Verify content does not overflow
    const scrollHeightSmall = await scrollableSmallContent.evaluate((el) => el.scrollHeight);
    const clientHeightSmall = await scrollableSmallContent.evaluate((el) => el.clientHeight);
    expect(scrollHeightSmall).toBeLessThanOrEqual(clientHeightSmall);

    // Attempt to scroll (should not change position)
    await scrollableSmallContent.evaluate((el) => {
      el.scrollTop = 100;
    });

    // Verify scroll position remains at top
    const scrollPosSmall = await scrollableSmallContent.evaluate((el) => el.scrollTop);
    expect(scrollPosSmall).toBe(0);

    // Verify page scroll remains unchanged
    const pageScrollYSmall = await page.evaluate(() => window.scrollY);
    expect(pageScrollYSmall).toBe(0);

    // Verify modal content text is visible
    const contentText = page.getByText(/short content/i);
    await expect(contentText).toBeVisible();

    // Close modal with close button
    const closeBtnSmall = page.getByRole('button', { name: /close|×/i });
    await expect(closeBtnSmall).toBeVisible();
    await closeBtnSmall.click();

    // Verify modal is closed
    await expect(smallModal).not.toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

test.describe('Modal Scroll Lock Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-test');
  });

  test('should prevent page scroll when modal is open', async ({ page }) => {
    // Verify body is scrollable before modal opens
    const body = page.locator('body');
    const overflowBefore = await body.evaluate((el) => window.getComputedStyle(el).overflow);
    expect(overflowBefore).toBe('visible');

    // Open modal using role-based locator
    const openModalBtn = page.getByRole('button', { name: /open modal/i });
    await openModalBtn.click();

    // Verify modal is visible using getByRole
    const modalDialog = page.getByRole('dialog');
    await expect(modalDialog).toBeVisible();

    // Verify body overflow is hidden
    const overflowAfter = await body.evaluate((el) => window.getComputedStyle(el).overflow);
    expect(overflowAfter).toBe('hidden');

    // Get initial scroll position
    const initialScrollY = await page.evaluate(() => window.scrollY);

    // Attempt to scroll
    await page.evaluate(() => window.scrollBy(0, 200));

    // Verify scroll position hasn't changed
    const finalScrollY = await page.evaluate(() => window.scrollY);
    expect(finalScrollY).toBe(initialScrollY);

    // Verify modal content is visible
    const modalContent = page.getByText(/modal content/i);
    await expect(modalContent).toBeVisible();
  });

  test('should restore page scroll when modal is closed', async ({ page }) => {
    // Open modal
    const openModalBtn = page.getByRole('button', { name: /open modal/i });
    await openModalBtn.click();

    // Verify modal is displayed
    const modalDialog = page.getByRole('dialog');
    await expect(modalDialog).toBeVisible();

    // Verify scroll is locked
    const body = page.locator('body');
    const overflowLocked = await body.evaluate((el) => window.getComputedStyle(el).overflow);
    expect(overflowLocked).toBe('hidden');

    // Close modal using role-based button locator
    const closeBtn = page.getByRole('button', { name: /close/i });
    await closeBtn.click();

    // Verify modal is gone
    await expect(modalDialog).not.toBeVisible();

    // Verify scroll is restored
    const overflowRestored = await body.evaluate((el) => window.getComputedStyle(el).overflow);
    expect(overflowRestored).toBe('visible');

    // Verify page is scrollable again
    const initialScrollY = await page.evaluate(() => window.scrollY);
    await page.evaluate(() => window.scrollBy(0, 150));
    const finalScrollY = await page.evaluate(() => window.scrollY);
    expect(finalScrollY).toBeGreaterThan(initialScrollY);
  });
});

