test.describe('Cookie Consent Banner', () => {
  test.beforeEach(async ({ page, context }) => {
    await context.clearCookies();
    await page.goto('/');
  });

  test('should display and hide cookie consent banner after accepting', async ({ page }) => {
    // Verify banner is visible on page load
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    // Verify title and description are visible
    const title = page.getByRole('heading', { name: /cookie consent/i });
    await expect(title).toBeVisible();

    const description = page.getByText(/we use cookies/i);
    await expect(description).toBeVisible();

    // Verify buttons exist
    const acceptButton = page.getByRole('button', { name: /accept/i });
    const rejectButton = page.getByRole('button', { name: /reject/i });
    await expect(acceptButton).toBeVisible();
    await expect(rejectButton).toBeVisible();

    // Listen for consent API call
    const responsePromise = page.waitForResponse(response => 
      response.url().includes('/api/consent/accept') && response.status() === 200
    );

    // Click accept button
    await acceptButton.click();

    // Wait for API response
    await responsePromise;

    // Verify banner disappears
    await expect(banner).not.toBeVisible();

    // Verify consent cookie is set
    const cookies = await page.context().cookies();
    const consentCookie = cookies.find(c => c.name === 'consent_accepted');
    expect(consentCookie).toBeDefined();
    expect(consentCookie?.value).toBe('true');

    // Verify banner does not reappear on page reload
    await page.reload();
    await expect(banner).not.toBeVisible();
  });

  test('should handle reject action and persist dismissal state across reloads', async ({ page }) => {
    // Verify banner is visible initially
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    // Get reject button using getByRole
    const rejectButton = page.getByRole('button', { name: /reject/i });
    await expect(rejectButton).toBeVisible();

    // Listen for reject API call
    const responsePromise = page.waitForResponse(response => 
      response.url().includes('/api/consent/reject') && response.status() === 200
    );

    // Click reject button
    await rejectButton.click();

    // Wait for API response
    await responsePromise;

    // Verify banner disappears after rejection
    await expect(banner).not.toBeVisible();

    // Verify rejection cookie is set with false value
    const cookies = await page.context().cookies();
    const consentCookie = cookies.find(c => c.name === 'consent_accepted');
    expect(consentCookie).toBeDefined();
    expect(consentCookie?.value).toBe('false');

    // Verify banner does not reappear on reload
    await page.reload();
    await expect(banner).not.toBeVisible();

    // Verify cookie persists
    const cookiesAfterReload = await page.context().cookies();
    const persistedCookie = cookiesAfterReload.find(c => c.name === 'consent_accepted');
    expect(persistedCookie?.value).toBe('false');
  });
});

