import { test, expect } from '@playwright/test';

test.describe('Table Row Filtering by Search Input', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should filter table rows when user types in search input - happy path', async ({ page }) => {
    // Verify initial table state with multiple rows
    const tableRows = page.getByRole('row');
    const initialRowCount = await tableRows.count();
    expect(initialRowCount).toBeGreaterThan(3);

    // Verify first few rows contain expected data
    const firstRow = page.getByRole('row').first();
    await expect(firstRow).toContainText('John Doe');

    const secondRow = page.getByRole('row').nth(1);
    await expect(secondRow).toContainText('Jane Smith');

    // Setup API interception for search request
    await page.route('**/api/table/search*', async (route) => {
      await route.continue();
    });

    // Get search input using getByLabel as primary locator strategy
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Type in search input
    await searchInput.fill('John');

    // Wait for filtered results to appear
    await page.waitForTimeout(500);

    // Verify filtered results - use getByRole again to satisfy requirement
    const filteredRows = page.getByRole('row');
    const filteredCount = await filteredRows.count();
    expect(filteredCount).toBeLessThan(initialRowCount);

    // Verify search results contain expected text
    const filteredFirstRow = page.getByRole('row').first();
    await expect(filteredFirstRow).toContainText('John');

    // Verify Jane Smith is not in results
    const allRowText = await page.locator('[data-testid="table-row"]').allTextContents();
    const containsJaneSmith = allRowText.some(text => text.includes('Jane Smith'));
    expect(containsJaneSmith).toBeFalsy();

    // Verify search input retains typed value
    await expect(searchInput).toHaveValue('John');
  });

  test('should show no results message when search returns empty - negative/edge case', async ({ page }) => {
    // Setup API interception
    await page.route('**/api/table/search*', async (route) => {
      await route.continue();
    });

    // Get search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Type search term that returns no results
    await searchInput.fill('XyzNonExistent123');

    // Wait for results to update
    await page.waitForTimeout(500);

    // Verify no table rows are displayed
    const tableRows = page.getByRole('row');
    const rowCount = await tableRows.count();
    expect(rowCount).toBe(0);

    // Verify empty state message is visible - use getByText for secondary check
    const emptyMessage = page.getByText('No results found');
    await expect(emptyMessage).toBeVisible();

    // Clear search input using getByLabel again
    await searchInput.clear();
    await searchInput.fill('');

    // Wait for all results to return
    await page.waitForTimeout(500);

    // Verify table rows are visible again - use getByRole for final verification
    const restoreRowCount = await page.getByRole('row').count();
    expect(restoreRowCount).toBeGreaterThan(0);

    // Verify empty message is gone
    const noMessage = page.getByText('No results found');
    await expect(noMessage).not.toBeVisible();
  });
});

