test.describe('Freeze First Column on Horizontal Scroll', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should freeze the first column when scrolling horizontally', async ({ page }) => {
    // Verify table is visible using getByRole
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify first column header is visible using getByRole
    const columnHeader = page.getByRole('columnheader', { name: /ID/i });
    await expect(columnHeader).toBeVisible();

    // Get initial position of first column
    const columnBBox = await columnHeader.boundingBox();
    const initialLeft = columnBBox.x;

    // Click freeze button on first column
    const freezeBtn = page.getByRole('button', { name: /freeze/i }).first();
    await freezeBtn.click();

    // Verify freeze indicator appears
    const freezeIndicator = page.getByText('📌');
    await expect(freezeIndicator).toBeVisible();

    // Scroll table horizontally
    const scrollContainer = page.locator('[data-testid="table-scroll-container"]');
    await scrollContainer.evaluate((el) => {
      el.scrollLeft = el.scrollWidth;
    });

    // Verify first column remains visible and in same position
    await expect(columnHeader).toBeVisible();
    const columnBBoxAfter = await columnHeader.boundingBox();
    const positionAfterScroll = columnBBoxAfter.x;
    expect(positionAfterScroll).toBe(initialLeft);

    // Verify other columns are not visible
    const nameColumn = page.getByRole('columnheader', { name: /Name/i });
    await expect(nameColumn).not.toBeVisible();
  });

  test('should unfreeze the first column and allow normal scrolling', async ({ page }) => {
    // Setup: freeze the first column
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    const freezeBtn = page.getByRole('button', { name: /freeze/i }).first();
    await freezeBtn.click();

    // Verify freeze indicator is present
    const freezeIndicator = page.getByText('📌');
    await expect(freezeIndicator).toBeVisible();

    // Scroll to verify frozen behavior
    const scrollContainer = page.locator('[data-testid="table-scroll-container"]');
    await scrollContainer.evaluate((el) => {
      el.scrollLeft = el.scrollWidth;
    });

    const columnHeader = page.getByRole('columnheader', { name: /ID/i });
    await expect(columnHeader).toBeVisible();

    // Scroll back to left
    await scrollContainer.evaluate((el) => {
      el.scrollLeft = 0;
    });

    // Click unfreeze button
    const unfreezeBtn = page.getByRole('button', { name: /unfreeze/i }).first();
    await unfreezeBtn.click();

    // Verify freeze indicator is gone
    await expect(freezeIndicator).not.toBeVisible();

    // Scroll horizontally
    await scrollContainer.evaluate((el) => {
      el.scrollLeft = el.scrollWidth;
    });

    // Verify first column is no longer visible (scrolled out)
    await expect(columnHeader).not.toBeVisible();

    // Scroll back to left
    await scrollContainer.evaluate((el) => {
      el.scrollLeft = 0;
    });

    // Verify normal scrolling behavior is restored
    await expect(columnHeader).toBeVisible();
  });
});

