import { test, expect } from '@playwright/test';

test.describe('File Upload Queue - Remove File Before Submit', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully remove a file from the upload queue before submission', async ({ page }) => {
    // Select and upload multiple files
    const fileInput = page.locator('[data-testid="file-input"]');
    await fileInput.setInputFiles([
      'playwright/fixtures/document1.pdf',
      'playwright/fixtures/document2.pdf',
      'playwright/fixtures/document3.pdf'
    ]);

    // Verify all three files are in the queue
    const queueItems = page.locator('[data-testid="upload-queue-item"]');
    await expect(queueItems).toHaveCount(3);

    const firstFile = page.locator('[data-testid="queue-file-name"]').first();
    const secondFile = page.locator('[data-testid="queue-file-name"]').nth(1);
    const thirdFile = page.locator('[data-testid="queue-file-name"]').nth(2);

    await expect(firstFile).toContainText('document1.pdf');
    await expect(secondFile).toContainText('document2.pdf');
    await expect(thirdFile).toContainText('document3.pdf');

    // Remove the second file from queue
    const removeButtons = page.locator('[data-testid="remove-file-btn"]');
    await removeButtons.nth(1).click();

    // Verify the file was removed and queue now has 2 items
    await expect(queueItems).toHaveCount(2);
    await expect(firstFile).toContainText('document1.pdf');
    await expect(secondFile).toContainText('document3.pdf');

    // Verify remove success message appears
    const successMessage = page.locator('[data-testid="success-message"]');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('File removed from queue');

    // Submit the remaining files
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();
    await submitButton.click();

    // Intercept and verify API call contains only 2 files
    const uploadPromise = page.waitForResponse(response => response.url().includes('/api/upload') && response.status() === 200);
    const uploadResponse = await uploadPromise;
    const responseBody = await uploadResponse.text();
    expect(responseBody).toContain('document1.pdf');
    expect(responseBody).toContain('document3.pdf');
    expect(responseBody).not.toContain('document2.pdf');

    // Verify success response
    const uploadSuccess = page.locator('[data-testid="upload-success"]');
    await expect(uploadSuccess).toBeVisible();
    await expect(uploadSuccess).toContainText('2 files uploaded successfully');
  });

  test('should handle edge case of removing all files from queue and preventing submission', async ({ page }) => {
    // Upload a single file
    const fileInput = page.locator('[data-testid="file-input"]');
    await fileInput.setInputFiles('playwright/fixtures/document1.pdf');

    // Verify file is in queue
    const queueItems = page.locator('[data-testid="upload-queue-item"]');
    await expect(queueItems).toHaveCount(1);

    // Remove the only file
    const removeButton = page.getByRole('button', { name: /remove/i }).first();
    await expect(removeButton).toBeVisible();
    await removeButton.click();

    // Verify queue is empty
    await expect(queueItems).toHaveCount(0);

    const emptyMessage = page.locator('[data-testid="empty-queue-message"]');
    await expect(emptyMessage).toBeVisible();
    await expect(emptyMessage).toContainText('No files in queue');

    // Verify submit button is disabled when queue is empty
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Verify validation error message appears on disabled submit attempt
    const validationError = page.locator('[data-testid="validation-error"]');
    await expect(validationError).toBeVisible();
    await expect(validationError).toContainText('Please add files before submitting');

    // Verify no upload request is made when queue is empty
    let uploadRequested = false;
    page.on('response', response => {
      if (response.url().includes('/api/upload')) {
        uploadRequested = true;
      }
    });

    // Attempt to submit should not trigger API call
    await submitButton.click();
    expect(uploadRequested).toBe(false);
  });
});

