test.describe('File Upload Retry Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should retry a failed upload without re-selecting the file', async ({ page }) => {
    // Intercept the initial upload request to simulate failure
    await page.route('**/api/upload', route => {
      route.abort('failed');
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('test-file.pdf');

    // Verify file name is displayed using getByRole
    const fileNameDisplay = page.getByRole('status');
    await expect(fileNameDisplay).toContainText('test-file.pdf');

    // Click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Wait for the failed request and verify error message
    await page.waitForTimeout(500);
    const errorMessage = page.getByText('Upload failed');
    await expect(errorMessage).toBeVisible();

    // Intercept the retry request to simulate success
    await page.unroute('**/api/upload');
    await page.route('**/api/upload', route => {
      route.continue();
    });

    // Mock successful response
    await page.route('**/api/upload', route => {
      route.abort('succeeded');
    });

    // Click retry button without re-selecting file
    const retryButton = page.getByRole('button', { name: 'Retry' });
    await retryButton.click();

    // Wait and verify success message
    await page.waitForTimeout(500);
    const successMessage = page.getByText('Upload successful');
    await expect(successMessage).toBeVisible();

    // Verify file name is still displayed
    await expect(fileNameDisplay).toContainText('test-file.pdf');
  });

  test('should handle retry failure and allow multiple retry attempts', async ({ page }) => {
    // Intercept initial upload request to fail
    await page.route('**/api/upload', route => {
      route.abort('failed');
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('test-document.docx');

    // Verify file name is displayed using getByRole
    const fileNameDisplay = page.getByRole('status');
    await expect(fileNameDisplay).toContainText('test-document.docx');

    // Click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Wait and verify first error
    await page.waitForTimeout(500);
    const errorMessage = page.getByText('Upload failed');
    await expect(errorMessage).toBeVisible();

    // Click retry button first time
    const retryButton = page.getByRole('button', { name: 'Retry' });
    await retryButton.click();

    // Wait and verify error persists
    await page.waitForTimeout(500);
    await expect(errorMessage).toBeVisible();

    // Verify file is still selected
    await expect(fileNameDisplay).toContainText('test-document.docx');

    // Remove route interception for successful retry
    await page.unroute('**/api/upload');

    // Click retry button second time to succeed
    await retryButton.click();

    // Wait and verify success message
    await page.waitForTimeout(500);
    const successMessage = page.getByText('Upload successful');
    await expect(successMessage).toBeVisible();
  });
});

