test.describe('Upload Button Disabled State During File Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should disable upload button while file is uploading and enable after completion', async ({ page }) => {
    // Setup: intercept the file upload API to simulate delay
    await page.route('**/api/upload', (route) => {
      setTimeout(() => {
        route.abort('failed');
      }, 2000);
    });

    // Setup: intercept with successful response
    await page.route('**/api/upload', async (route) => {
      await new Promise((resolve) => setTimeout(resolve, 2000));
      await route.continue();
    });

    // Get upload button by role to verify initial state
    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await expect(uploadButton).toBeEnabled();

    // Get file input and upload a file
    const fileInput = page.getByLabel(/select file/i);
    await fileInput.setInputFiles('tests/fixtures/sample-file.pdf');

    // Click the upload button
    await uploadButton.click();

    // Assert that upload button is disabled during upload
    await expect(uploadButton).toBeDisabled();
    await expect(uploadButton).toContainText('Uploading...');

    // Wait for upload to complete
    await page.waitForResponse((response) => response.url().includes('/api/upload'));

    // Assert that upload button is enabled after upload completes
    await expect(uploadButton).toBeEnabled();
    await expect(uploadButton).toContainText('Upload File');

    // Assert success message appears
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();
  });

  test('should keep upload button disabled if upload fails and allow retry', async ({ page }) => {
    // Setup: intercept the file upload API to simulate failure
    await page.route('**/api/upload', (route) => {
      route.abort('failed');
    });

    // Get upload button by role
    const uploadButton = page.getByRole('button', { name: /upload file/i });

    // Get file input and upload a file
    const fileInput = page.getByLabel(/select file/i);
    await fileInput.setInputFiles('tests/fixtures/sample-file.pdf');

    // Click the upload button
    await uploadButton.click();

    // Assert that upload button is disabled during upload attempt
    await expect(uploadButton).toBeDisabled();

    // Wait for failure to be processed
    await page.waitForTimeout(1500);

    // Assert that button is enabled again to allow retry
    await expect(uploadButton).toBeEnabled();

    // Assert error message is displayed
    const errorMessage = page.getByText(/upload failed/i);
    await expect(errorMessage).toBeVisible();

    // Update route to succeed for retry
    await page.route('**/api/upload', async (route) => {
      await route.continue();
    });

    // Verify retry is possible
    await uploadButton.click();
    await expect(uploadButton).toBeDisabled();
  });
});

