  });

  test('should successfully paste image from clipboard into upload area', async ({ page }) => {
    const uploadArea = page.getByRole('region', { name: /upload/i });
    await expect(uploadArea).toBeVisible();

    const confirmButton = page.getByRole('button', { name: /confirm|upload/i });
    await expect(confirmButton).toBeVisible();

    // Create a mock image blob and simulate paste event
    const imageBlob = await page.evaluate(() => {
      return fetch('/fixtures/test-image.png')
        .then(res => res.blob())
        .then(blob => blob);
    });

    // Get upload area and dispatch paste event with image
    await page.locator('[data-testid="upload-area"]').evaluate((element) => {
      const file = new File(
        [new Uint8Array([137, 80, 78, 71])],
        'test-image.png',
        { type: 'image/png' }
      );
      const dataTransfer = new DataTransfer();
      dataTransfer.items.add(file);
      const pasteEvent = new ClipboardEvent('paste', {
        clipboardData: dataTransfer,
        bubbles: true,
        cancelable: true,
      });
      element.dispatchEvent(pasteEvent);
    });

    // Verify preview appears
    const uploadPreview = page.getByText(/test-image\.png/i);
    await expect(uploadPreview).toBeVisible();

    // Verify status message
    const statusMessage = page.locator('[data-testid="upload-status"]');
    await expect(statusMessage).toContainText('successful');

    // Click confirm button
    await confirmButton.click();

    // Verify success message
    const successMsg = page.getByText(/image uploaded/i);
    await expect(successMsg).toBeVisible();
  });

  test('should reject non-image files pasted into upload area', async ({ page }) => {
    const uploadArea = page.getByRole('region', { name: /upload/i });
    await expect(uploadArea).toBeVisible();

    const confirmButton = page.getByRole('button', { name: /confirm|upload/i });
    await expect(confirmButton).toBeVisible();

    // Dispatch paste event with non-image file
    await page.locator('[data-testid="upload-area"]').evaluate((element) => {
      const file = new File(
        [new TextEncoder().encode('This is plain text')],
        'document.txt',
        { type: 'text/plain' }
      );
      const dataTransfer = new DataTransfer();
      dataTransfer.items.add(file);
      const pasteEvent = new ClipboardEvent('paste', {
        clipboardData: dataTransfer,
        bubbles: true,
        cancelable: true,
      });
      element.dispatchEvent(pasteEvent);
    });

    // Verify error message appears
    const errorMessage = page.getByText(/only image files are allowed/i);
    await expect(errorMessage).toBeVisible();

    // Verify confirm button is disabled
    await expect(confirmButton).toBeDisabled();

    // Verify preview does not appear
    const uploadPreview = page.locator('[data-testid="upload-preview"]');
    await expect(uploadPreview).not.toBeVisible();
  });
});

