test.describe('Dynamic Content Updates Accessibility - Screen Reader Announcements', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should announce dynamic content updates via ARIA live regions to screen readers', async ({ page }) => {
    // Verify live region container exists with correct ARIA attributes
    const liveRegion = page.getByRole('status');
    await expect(liveRegion).toBeVisible();
    await expect(liveRegion).toHaveAttribute('aria-live', 'polite');
    await expect(liveRegion).toHaveAttribute('aria-atomic', 'true');

    // Get refresh button by role
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await expect(refreshButton).toBeVisible();

    // Trigger dynamic content update
    await refreshButton.click();

    // Wait for dynamic update to complete
    await page.waitForLoadState('networkidle');

    // Verify announcement text appears in live region
    await expect(liveRegion).toContainText('Content has been updated');

    // Verify announcement is hidden from visual display
    const srOnly = page.locator('[data-testid="live-region"]');
    await expect(srOnly).toHaveClass(/sr-only/);

    // Verify content in main container is also updated
    const contentContainer = page.getByRole('main');
    await expect(contentContainer).toContainText('Updated');

    // Verify button remains accessible after update
    await expect(refreshButton).not.toBeDisabled();
  });

  test('should handle missing live region and alert when screen reader announcements cannot be made', async ({ page }) => {
    // Get live region reference before removal
    const liveRegion = page.getByRole('status');

    // Remove live region to simulate failure scenario
    await page.evaluate(() => {
      const region = document.querySelector('[data-testid="live-region"]');
      if (region) region.remove();
