    // Verify content container still exists and is accessible
    const contentContainer = page.getByRole('main');
    await expect(contentContainer).toBeVisible();

    // Verify that critical accessibility features are missing
    const missingLiveRegion = page.getByRole('status');
    await expect(missingLiveRegion).not.toBeVisible();
  });
});

