    // Verify footer content
    const footerContent = page.getByText(/Footer/);
    await expect(footerContent).toBeVisible();

    // Verify tabindex is correct
    await expect(primaryButton).toHaveAttribute('tabindex', '0');
    await expect(secondaryButton).toHaveAttribute('tabindex', '0');

    // Check that elements are not absolutely positioned in a way that breaks order
    const introParagraphElement = page.locator('[data-testid="intro-paragraph"]');
    const computedStyle = await introParagraphElement.evaluate(el => window.getComputedStyle(el).position);
    expect(computedStyle).not.toBe('absolute');

