    await mainHeading.focus();
    let focusedElement = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
    expect(focusedElement).toBe('main-heading');
  });

  test('should identify when reading order does not match visual order (negative case)', async ({ page }) => {
    // Verify skip link exists and is accessible
    const skipLink = page.getByRole('link', { name: /Skip to main content/i });
    await expect(skipLink).toBeVisible();

    // Get primary navigation button
    const navButton = page.getByRole('button', { name: /Menu/i });
    if (await navButton.isVisible()) {
      await expect(navButton).toBeVisible();
    }

    // Ensure misaligned content does not exist
    const misalignedContent = page.locator('[data-testid="misaligned-content"]');
    await expect(misalignedContent).not.toBeVisible();

    // Verify no extreme negative margins breaking reading order
    const buttons = page.getByRole('button');
    const buttonCount = await buttons.count();
    for (let i = 0; i < buttonCount; i++) {
      const button = buttons.nth(i);
      const marginLeft = await button.evaluate(el => window.getComputedStyle(el).marginLeft);
      const marginTop = await button.evaluate(el => window.getComputedStyle(el).marginTop);
