test.describe('Prefers Reduced Motion Accessibility Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should respect prefers-reduced-motion when enabled and disable animations', async ({ page, context }) => {
    // Emulate prefers-reduced-motion: reduce
    await context.emulateMedia({ reducedMotion: 'reduce' });

    // Reload page with the media query emulation applied
    await page.goto('/');

    // Verify animated button is visible and has no-animation class
    const animatedButton = page.getByRole('button', { name: /animated action/i });
    await expect(animatedButton).toBeVisible();
    await expect(animatedButton).toHaveClass(/no-animation/);

    // Verify that transition duration is set to 0s
    const buttonComputedStyle = await animatedButton.evaluate((el) => {
      return window.getComputedStyle(el).transitionDuration;
    });
    expect(buttonComputedStyle).toBe('0s');

    // Interact with button and verify feedback appears immediately
    await animatedButton.click();
    const feedbackMessage = page.getByText(/action completed/i);
    await expect(feedbackMessage).toBeVisible();
    await expect(feedbackMessage).toContainText('Action completed');
  });

  test('should allow animations when prefers-reduced-motion is not set', async ({ page, context }) => {
    // Emulate prefers-reduced-motion: no-preference (default)
    await context.emulateMedia({ reducedMotion: 'no-preference' });

    // Reload page with the media query emulation applied
    await page.goto('/');

    // Verify animated button is visible and does not have no-animation class
    const animatedButton = page.getByRole('button', { name: /animated action/i });
    await expect(animatedButton).toBeVisible();
    const hasNoAnimationClass = await animatedButton.evaluate((el) => {
      return el.classList.contains('no-animation');
    });
    expect(hasNoAnimationClass).toBe(false);

    // Verify that transition duration is greater than 0s
    const buttonComputedStyle = await animatedButton.evaluate((el) => {
      return window.getComputedStyle(el).transitionDuration;
    });
    expect(buttonComputedStyle).not.toBe('0s');

    // Click button and verify smooth animation feedback
    await animatedButton.click();
    const feedbackLabel = page.getByLabel(/animation status/i);
    await expect(feedbackLabel).toBeVisible();
    await expect(feedbackLabel).toContainText('Animated action completed');
  });
});

