test.describe('Image Scaling on Mobile Viewport', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/gallery');
    await page.setViewportSize({ width: 390, height: 844 });
  });

  test('should scale images down to fit screen width on mobile viewport', async ({ page }) => {
