    await expect(imageGallery).toBeVisible();

    const imageContainer = page.getByRole('img').first();
    await expect(imageContainer).toBeVisible();

    const images = page.getByRole('img');
    const imageCount = await images.count();

    for (let i = 0; i < imageCount; i++) {
      const img = images.nth(i);
      const boundingBox = await img.boundingBox();
      expect(boundingBox.width).toBeLessThanOrEqual(390);
    }

    const wrapper = page.locator('[data-testid="image-container"]');
    const maxWidth = await wrapper.evaluate(el => window.getComputedStyle(el).maxWidth);
    expect(maxWidth).toMatch(/100%|auto/);

    await page.route('/api/images', route => {
      route.continue();
    });

    const loadMoreBtn = page.getByRole('button', { name: /load more/i });
    await expect(loadMoreBtn).toBeVisible();
    await loadMoreBtn.click();

    await page.waitForLoadState('networkidle');
    const lastImage = page.getByRole('img').last();
    const lastBox = await lastImage.boundingBox();
    expect(lastBox.width).toBeLessThanOrEqual(390);
  });

  test('should handle edge case when image has fixed width exceeding viewport', async ({ page }) => {
    const firstImage = page.getByRole('img').first();
    await expect(firstImage).toBeVisible();

    await firstImage.evaluate(el => {
      el.style.width = '1200px';
    });

    const boundingBox = await firstImage.boundingBox();
    expect(boundingBox.width).toBeLessThanOrEqual(390);

    const container = page.getByRole('region', { name: /gallery/i });
    await expect(container).toBeVisible();

    const overflowStyle = await container.evaluate(el => window.getComputedStyle(el).overflowX);
    expect(overflowStyle).not.toEqual('visible');

    const computedMaxWidth = await firstImage.evaluate(el => window.getComputedStyle(el).maxWidth);
    expect(computedMaxWidth).toMatch(/100%|auto/);

    await page.setViewportSize({ width: 375, height: 667 });
    const smallViewportBox = await firstImage.boundingBox();
    expect(smallViewportBox.width).toBeLessThanOrEqual(375);

    const width = await firstImage.evaluate(el => el.style.width);
    expect(width).not.toBe('1200px');
  });
});

