test.describe('Horizontal Scrolling Disabled on Main Layout - Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.setViewportSize({ width: 375, height: 667 });
  });

  test('Happy Path: Main layout should not allow horizontal scrolling on mobile viewport', async ({ page }) => {
    // Verify main layout container is visible using getByRole
    const mainLayout = page.getByRole('main');
    await expect(mainLayout).toBeVisible();

    // Get initial horizontal scroll position
    const initialScrollLeft = await page.locator('[data-testid="main-layout"]').evaluate(el => el.scrollLeft);
    expect(initialScrollLeft).toBe(0);

    // Verify overflow-x CSS property is set to hidden
    const overflowX = await page.locator('[data-testid="main-layout"]').evaluate(el => 
      window.getComputedStyle(el).overflowX
    );
    expect(overflowX).toBe('hidden');

    // Verify body element doesn't have horizontal scroll using getByRole
    const bodyElement = page.locator('body');
    const bodyOverflowX = await bodyElement.evaluate(el => 
      window.getComputedStyle(el).overflowX
    );
    expect(bodyOverflowX).toBe('hidden');

    // Verify window doesn't have horizontal scrollbar
    const hasHorizontalScroll = await page.evaluate(() => {
      return document.documentElement.scrollWidth > document.documentElement.clientWidth;
    });
    expect(hasHorizontalScroll).toBe(false);

    // Attempt keyboard navigation and verify no scroll occurs
    await page.keyboard.press('ArrowRight');
    const scrollAfterKeypress = await page.locator('[data-testid="main-layout"]').evaluate(el => el.scrollLeft);
    expect(scrollAfterKeypress).toBe(0);
  });

  test('Negative Path: Verify horizontal scrolling is disabled even with wide content', async ({ page }) => {
    // Verify wide content exists and is visible using getByRole
    const mainLayout = page.getByRole('main');
    await expect(mainLayout).toBeVisible();

    const wideContent = page.getByRole('contentinfo');
    await expect(wideContent).toBeVisible();

    // Simulate touch swipe gesture horizontally
    const layoutElement = page.locator('[data-testid="main-layout"]');
    await layoutElement.dispatchEvent('touchstart', { touches: [{ clientX: 300 }] });
    await layoutElement.dispatchEvent('touchmove', { touches: [{ clientX: 100 }] });
    await layoutElement.dispatchEvent('touchend');

    // Verify scroll position remains at 0 after touch attempt
    const scrollLeftAfterTouch = await layoutElement.evaluate(el => el.scrollLeft);
    expect(scrollLeftAfterTouch).toBe(0);

    // Verify window scroll hasn't changed
    const windowScrollX = await page.evaluate(() => window.scrollX);
    expect(windowScrollX).toBe(0);

    // Verify overflow-x is still hidden
    const overflowX = await layoutElement.evaluate(el => 
      window.getComputedStyle(el).overflowX
    );
    expect(overflowX).toBe('hidden');

    // Verify all child elements have max-width constraint
    const childElements = await page.locator('[data-testid="main-layout"] > *').all();
    for (const child of childElements) {
      const maxWidth = await child.evaluate(el => window.getComputedStyle(el).maxWidth);
      expect(maxWidth === '100%' || maxWidth.includes('px')).toBeTruthy();
    }

    // Verify content doesn't overflow using getByRole for additional context
    const contentArea = page.getByRole('article').or(page.getByRole('section'));
    const contentWidth = await contentArea.evaluate(el => el.scrollWidth);
    const viewportWidth = await contentArea.evaluate(el => el.clientWidth);
    expect(contentWidth).toBeLessThanOrEqual(viewportWidth);
  });
});

