  });

  test('should display sticky footer navigation and remain visible when scrolling on mobile', async ({ page }) => {
    // Verify footer navigation is visible on page load
    const footerNav = page.getByRole('navigation', { name: /footer/i });
    await expect(footerNav).toBeVisible();

    // Verify footer nav contains expected navigation buttons
    const homeButton = page.getByRole('button', { name: /home/i });
    const searchButton = page.getByRole('button', { name: /search/i });
    const profileButton = page.getByRole('button', { name: /profile/i });

