    await expect(searchButton).toBeVisible();
    await expect(profileButton).toBeVisible();

    // Get main content and scroll down
    const mainContent = page.locator('[data-testid="main-content"]');
    await expect(mainContent).toBeVisible();
    await mainContent.scrollIntoViewIfNeeded();
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));

    // Verify footer navigation remains visible after scrolling
    await expect(footerNav).toBeVisible();

    // Verify footer has sticky positioning CSS
    const positionValue = await footerNav.evaluate(el => 
      window.getComputedStyle(el).position
    );
    expect(positionValue).toBe('fixed');

    const bottomValue = await footerNav.evaluate(el => 
      window.getComputedStyle(el).bottom
    );
    expect(bottomValue).toBe('0px');

