import { test, expect } from '@playwright/test';

test.describe('Video Player Responsive Resize on Tablet Viewports', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/video-player');
  });

  test('should resize video player proportionally when viewport changes to tablet size', async ({ page }) => {
    // Set initial desktop viewport
    await page.setViewportSize({ width: 1920, height: 1080 });

    // Verify video player is visible on desktop
    const videoPlayer = page.getByRole('region', { name: /video player/i });
    await expect(videoPlayer).toBeVisible();

    const desktopBox = await videoPlayer.boundingBox();
    const desktopWidth = desktopBox.width;
    const desktopHeight = desktopBox.height;
    expect(desktopWidth).toBeGreaterThan(0);
    expect(desktopHeight).toBeGreaterThan(0);

    // Resize to tablet viewport (iPad)
    await page.setViewportSize({ width: 768, height: 1024 });

    // Verify video player still visible and resized
    const tabletPlayer = page.getByRole('region', { name: /video player/i });
    await expect(tabletPlayer).toBeVisible();

    const tabletBox = await tabletPlayer.boundingBox();
    const tabletWidth = tabletBox.width;
    const tabletHeight = tabletBox.height;
    expect(tabletWidth).toBeLessThan(desktopWidth);
    expect(tabletHeight).toBeLessThan(desktopHeight);

    // Verify aspect ratio is maintained (16:9 within tolerance)
    const aspectRatio = tabletWidth / tabletHeight;
    expect(Math.abs(aspectRatio - 16 / 9)).toBeLessThan(0.1);

    // Verify play button is still accessible
    const playButton = page.getByRole('button', { name: /play/i });
    await expect(playButton).toBeVisible();
    await playButton.click();

    const video = page.getByRole('document');
    await expect(video).toHaveAttribute('data-playing', 'true');
  });

  test('should handle edge case of very small tablet viewport without breaking layout', async ({ page }) => {
    // Set very small tablet viewport
    await page.setViewportSize({ width: 480, height: 600 });

    // Verify video player is visible
    const videoPlayer = page.getByRole('region', { name: /video player/i });
    await expect(videoPlayer).toBeVisible();

    // Verify player does not overflow container
    const container = page.getByRole('main');
    const containerBox = await container.boundingBox();
    const playerBox = await videoPlayer.boundingBox();
    expect(playerBox.width).toBeLessThanOrEqual(containerBox.width);

    // Verify controls are still visible and not hidden
    const volumeButton = page.getByRole('button', { name: /volume/i });
    const fullscreenButton = page.getByRole('button', { name: /fullscreen/i });

    await expect(volumeButton).toBeVisible();
    await expect(fullscreenButton).toBeVisible();

    // Verify minimum dimensions are respected (minimum 280x157)
    expect(playerBox.width).toBeGreaterThanOrEqual(280);
    expect(playerBox.height).toBeGreaterThanOrEqual(157);

    // Verify aspect ratio still maintained
    const aspectRatio = playerBox.width / playerBox.height;
    expect(Math.abs(aspectRatio - 16 / 9)).toBeLessThan(0.15);
  });
});

