test.describe('Expired Promo Code Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display error message when applying an expired promo code', async ({ page }) => {
    // Arrange: Set up API intercept for promo code validation
    await page.route('**/api/promo-codes/validate', (route) => {
      route.abort('failed');
    });

    // Act: Fill in promo code input using getByLabel
    const promoInput = page.getByLabel('Promo Code');
    await expect(promoInput).toBeVisible();
    await promoInput.fill('EXPIRED2023');

    // Act: Click apply button using getByRole
    const applyButton = page.getByRole('button', { name: /apply/i });
    await expect(applyButton).toBeVisible();
    await applyButton.click();

    // Wait for error state
    await page.waitForTimeout(500);

    // Assert: Verify error message is displayed using getByText
    const errorMessage = page.getByText(/this promo code has expired/i);
    await expect(errorMessage).toBeVisible();

    // Assert: Verify error styling on input
    await expect(promoInput).toHaveClass(/error-state/);

    // Assert: Verify discount amount is zero using getByText
    const discountAmount = page.getByText('$0.00');
    await expect(discountAmount).toBeVisible();
  });

  test('should clear error message when user enters a valid promo code after invalid attempt', async ({ page }) => {
    // Arrange: Set up initial failed intercept
    let requestCount = 0;
    await page.route('**/api/promo-codes/validate', (route) => {
      requestCount++;
      if (requestCount === 1) {
        route.abort('failed');
      } else {
        route.continue();
      }
    });

    // Act: First attempt with expired code using getByLabel
    const promoInput = page.getByLabel('Promo Code');
    await expect(promoInput).toBeVisible();
    await promoInput.fill('EXPIRED2023');

    // Act: Click apply button using getByRole
    const applyButton = page.getByRole('button', { name: /apply/i });
    await expect(applyButton).toBeVisible();
    await applyButton.click();

    // Wait for error state
    await page.waitForTimeout(500);

    // Assert: Error message is visible
    const errorMessage = page.getByText(/this promo code has expired/i);
    await expect(errorMessage).toBeVisible();

    // Arrange: Set up successful response for second attempt
    await page.route('**/api/promo-codes/validate', (route) => {
      route.continue();
    });

    // Act: Clear field and enter valid code
    await promoInput.clear();
    await promoInput.fill('VALID2024');
    await applyButton.click();

    // Wait for success state
    await page.waitForTimeout(500);

    // Assert: Error message should not exist
    await expect(page.getByText(/this promo code has expired/i)).not.toBeVisible();

    // Assert: Success message should be visible using getByText
    const successMessage = page.getByText(/promo code applied successfully/i);
    await expect(successMessage).toBeVisible();

    // Assert: Discount should be applied
    const discountAmount = page.getByText(/\$15\.00/);
    await expect(discountAmount).toBeVisible();
  });
});

