test.describe('User Timezone Settings in Profile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile/settings');
  });

  test('should successfully set timezone to a valid option', async ({ page }) => {
    // Set up API interception for timezone update
    await page.route('**/api/profile/timezone', route => {
      route.continue();
    });

    // Navigate to timezone section using role-based selector
    const settingsNav = page.getByRole('button', { name: /profile settings/i });
    await expect(settingsNav).toBeVisible();
    await settingsNav.click();

    // Verify timezone section is visible
    const timezoneSection = page.getByText('Timezone Settings');
    await expect(timezoneSection).toBeVisible();

    // Open timezone dropdown using label
    const timezoneDropdown = page.getByLabel('Select your timezone');
    await expect(timezoneDropdown).toBeVisible();
    await timezoneDropdown.click();

    // Select Pacific Standard Time from dropdown
    const pstOption = page.getByRole('option', { name: /pacific standard time/i });
    await expect(pstOption).toBeVisible();
    await pstOption.click();

    // Verify selection is displayed in dropdown
    await expect(timezoneDropdown).toHaveValue('America/Los_Angeles');

    // Click save button using role selector
    const saveButton = page.getByRole('button', { name: /save timezone/i });
    await expect(saveButton).toBeVisible();

    // Intercept the PUT request and wait for success
    const updatePromise = page.waitForResponse(response =>
      response.url().includes('/api/profile/timezone') && response.status() === 200
    );

    await saveButton.click();
    const response = await updatePromise;
    expect(response.status()).toBe(200);

    // Verify success message appears
    const successMessage = page.getByText('Timezone updated successfully');
    await expect(successMessage).toBeVisible();

    // Verify timezone persists after page reload
