    await expect(settingsNav).toBeVisible();
    await settingsNav.click();

    // Verify timezone section is visible
    const timezoneSection = page.getByText('Timezone Settings');
    await expect(timezoneSection).toBeVisible();

    // Verify timezone dropdown has placeholder text (no selection)
    const timezoneDropdown = page.getByLabel('Select your timezone');
    await expect(timezoneDropdown).toHaveValue('');

    // Attempt to save without making a selection
    const saveButton = page.getByRole('button', { name: /save timezone/i });
    await saveButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('Timezone selection is required');
    await expect(errorMessage).toBeVisible();

    // Verify save button is still enabled for retry
    await expect(saveButton).toBeEnabled();

    // Verify the dropdown still has no value after error
    await expect(timezoneDropdown).toHaveValue('');

    // Set up API interception to verify no call is made on second attempt
    let apiCallMade = false;
    await page.route('**/api/profile/timezone', route => {
      apiCallMade = true;
      route.continue();
    });

    // Click save again without selecting timezone
    await saveButton.click();

    // Small delay to ensure any pending requests are captured
    await page.waitForTimeout(500);

    // Verify no API call was made
    expect(apiCallMade).toBe(false);
  });
});

