    await expect(errorMessage).not.toBeVisible();

    // Verify we remain on profile page
    const profileHeader = page.getByRole('heading', { name: /my profile/i });
    await expect(profileHeader).toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

test.describe('User Language Preference in Profile Settings', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile/settings');
    await page.waitForResponse(response => response.url().includes('/api/user/profile'));
  });

  test('should successfully set language preference to Spanish and persist the change', async ({ page }) => {
    const languageDropdown = page.getByRole('button', { name: /language/i });
    await expect(languageDropdown).toBeVisible();
    await languageDropdown.click();

    const spanishOption = page.getByRole('option', { name: /español/i });
    await expect(spanishOption).toBeVisible();
    await spanishOption.click();

    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    await page.waitForResponse(response => 
      response.url().includes('/api/user/profile/language') && response.status() === 200
    );

    const successMessage = page.getByText(/language preference updated/i);
    await expect(successMessage).toBeVisible();

    const updatedDropdown = page.getByRole('button', { name: /español/i });
    await expect(updatedDropdown).toContainText('Español');
  });

  test('should show error message when language update fails due to network error', async ({ page }) => {
    await page.route('/api/user/profile/language', route => {
      route.abort('failed');
    });

    const languageDropdown = page.getByRole('button', { name: /language/i });
    await languageDropdown.click();

    const frenchOption = page.getByRole('option', { name: /français/i });
    await frenchOption.click();

    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    const errorMessage = page.getByText(/failed to update language preference/i);
    await expect(errorMessage).toBeVisible();

    const dropdownText = page.getByRole('button', { name: /language/i });
    await expect(dropdownText).not.toContainText('Français');
  });
});

import { test, expect } from '@playwright/test';

test.describe('User Profile Update Confirmation Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
    await page.waitForLoadState('networkidle');
  });

  test('should display confirmation message after successfully updating profile', async ({ page }) => {
    const firstNameInput = page.getByLabel('First Name');
    const lastNameInput = page.getByLabel('Last Name');
    const emailInput = page.getByLabel('Email');
    const saveButton = page.getByRole('button', { name: 'Save Profile' });
    const successMessage = page.getByText('Profile updated successfully');

    await expect(firstNameInput).toBeVisible();
    await expect(lastNameInput).toBeVisible();

    await firstNameInput.fill('John');
    await lastNameInput.fill('Doe');
    await emailInput.fill('john.doe@example.com');

    await page.route('**/api/profile', route => {
      route.abort();
    });

    await page.route('**/api/profile', route => {
      route.continue({
        status: 200,
        body: JSON.stringify({
          success: true,
          message: 'Profile updated successfully'
        })
      });
    });

    await saveButton.click();
    await page.waitForLoadState('networkidle');

    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('Profile updated successfully');
  });

  test('should handle profile update failure and display error message', async ({ page }) => {
    const emailInput = page.getByLabel('Email');
    const saveButton = page.getByRole('button', { name: 'Save Profile' });
    const errorMessage = page.getByText('Invalid email format');

    await expect(emailInput).toBeVisible();
    await expect(saveButton).toBeVisible();

    await emailInput.fill('invalid-email');

    await page.route('**/api/profile', route => {
      route.continue({
        status: 400,
        body: JSON.stringify({
          success: false,
          message: 'Invalid email format'
        })
      });
    });

    await saveButton.click();
    await page.waitForLoadState('networkidle');

    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Invalid email format');

    const successMessage = page.getByText('Profile updated successfully');
    await expect(successMessage).not.toBeVisible();
  });
});
